  "请求等待超时，请检查节点和网络状态后重试。": "Время ожидания запроса истекло. Проверьте состояние узла и сети и повторите попытку.",
  "凭据存储方式与当前 Profile 不匹配；请保留原目录并使用新的 Profile 重新登录。": "Хранилище учётных данных не соответствует этому профилю. Сохраните исходный каталог и войдите с новым профилем.",
  "开发环境使用权限受限的本机 JSON 保存凭据，不使用系统密钥存储。": "В среде разработки учётные данные хранятся в закрытых локальных файлах JSON без использования системного хранилища ключей.",
  "采集器 · 仅同步本设备": "Сборщик · синхронизация только этого устройства",
  "设备权限": "Разрешения устройства",
  "本人客户端 · 完整权限": "Личный клиент · полный доступ",
  "独立采集器 · 仅同步": "Автономный сборщик · только синхронизация",
  "仅供独立采集程序使用：同步绑定设备的资料和来源，不能浏览归档或管理中央。Mac 和 Android 完整客户端请选择本人客户端。": "Для автономных программ сбора: синхронизация содержимого и источников привязанного устройства без просмотра архива и управления центральным узлом. Для полных клиентов Mac и Android выберите «Личный клиент».",
  "重新配对时，请选择原设备以保留身份。成功配对后会替换该设备同权限类型的旧凭据。": "При повторном сопряжении выберите исходное устройство, чтобы сохранить его идентичность. После успешного сопряжения прежние учётные данные того же типа разрешений заменяются.",
  "将邀请交给独立采集程序": "Передайте это приглашение автономному сборщику",
  "采集程序兑换后应检查 collector 身份和采集协议。此邀请不用于 Mac 或 Android 完整客户端登录。": "После активации сборщик должен проверить свою идентичность сборщика и протокол приёма. Это приглашение не подходит для входа в полные клиенты Mac или Android.",
  "屏幕录制": "Запись экрана",
  "辅助功能": "Универсальный доступ",
  "内容记录：优先提取文章或商品字段，未取得结构化内容时截图。": "Содержимое: сначала извлекаются поля статьи или товара; если структурированное содержимое недоступно, делается снимок экрана.",
  "仅应用活动：记录应用与时长。不记录：跳过该应用。": "Только активность: записываются приложение и длительность. «Не записывать»: приложение пропускается.",
  "隐私过滤不通过时不会回退截图。": "При отказе фильтра конфиденциальности снимок экрана не делается.",
  "记录和索引为 JSON，图片保留原始格式。这些是本应用专用目录，不是共享相册；卸载应用会删除本机文件。移除存储卡后会停止使用该位置并提示，不会切到空目录；重新连接后可恢复。": "Записи и индексы используют JSON; изображения сохраняют исходный формат. Это закрытые каталоги приложения, а не общий альбом; удаление приложения удаляет локальные файлы. Извлечение карты памяти прекращает доступ к этому расположению с уведомлением, без переключения на пустой каталог. Повторное подключение восстанавливает доступ.",
  "{0} 条 · 第 {1} 页": "Записей: {0} · страница {1}",
  "关闭预览": "Закрыть предпросмотр",
  "先存本机；连接中央整理后，可搜索和提问。": "Сначала сохраняется локально. Подключитесь к центральному узлу и обработайте содержимое, чтобы искать и задавать вопросы.",
