  "点击日期查看同步历史。接收完成后，中央可能仍在识别与整理。": "Выберите дату для просмотра истории синхронизации. Центральный узел может всё ещё распознавать и обрабатывать полученное содержимое.",
  "按来源汇总": "Сводка по источникам",
  "所选范围接收 / 当前待传": "Получено в диапазоне / ожидает сейчас",
