  "历史按当前节点与设备统计；传输量包含失败尝试，不等于远端存储占用。待复核项不会被自动重试放行。": "История ограничена текущим узлом и устройством. Объём передачи включает неудачные попытки и не отражает размер удалённого хранилища. Автоматические повторы не обходят проверку конфиденциальности.",
  "同步详情": "Подробности синхронизации",
