  "生活回顾已保存": "Обзор жизни сохранён",
  "模型、记忆、文件处理与飞书设置可直接保存并生效；其他偏好通过部署草稿修改并重启。离开有未保存修改的配置页面时会先提醒。": "Настройки моделей, памяти, обработки файлов и Feishu применяются при сохранении. Остальные параметры изменяются через черновик развёртывания с перезапуском. При уходе со страницы конфигурации с несохранёнными изменениями выводится предупреждение.",
  "文件与语音": "Файлы и речь",
  "本地语音模型、转写与文件处理策略": "Локальные модели речи, транскрибация и политики обработки файлов",
  "未提供文字识别状态，无法判断是否已处理。": "Состояние распознавания текста не предоставлено; завершённость обработки неизвестна.",
  "高级：遮挡 JSON": "Дополнительно: маскировать JSON",
  "本机数据格式已退役，请清除应用存储后重新设置。": "Этот локальный формат данных выведен из использования. Очистите хранилище приложения и настройте заново.",
  "整理所选记忆": "Консолидировать выбранную память",
  "从这条记忆开始整理": "Консолидировать, начиная с этой записи памяти",
  "从当前精选记忆开始，模型会按需检索你仍可读取的相关资料和原文；结果可能为空，也可能产生经独立审核的新记忆。": "Начиная с выбранной записи памяти, модель может запрашивать связанные записи и оригиналы, которые вам ещё доступны. Результат может быть пустым или стать новой записью памяти после независимой проверки.",
  "仅选择此卡作为整合起点": "Только эта карта выбрана как отправная точка",
  "请先选择一条当前有效的精选记忆。": "Сначала выберите действующую избранную запись памяти.",
