  "前往模型与服务配置": "Открыть настройки «Модели и службы»",
  "先配置 Memory 功能默认模型，再开始手动整理。": "Настройте модель функции «Память» по умолчанию перед запуском консолидации вручную.",
  "正在提交…": "Отправка…",
  "整理这条记忆": "Консолидировать эту запись памяти",
