  "先选择中央节点。本机记录可以继续保存；选择节点后，中央资料仍需单独登录。": "Сначала выберите центральный узел. Записи можно продолжать сохранять локально; для материалов центрального узла требуется отдельный вход.",
  "中央界面暂时无法打开。本机记录不受影响；请检查节点地址和网络后重试，或打开连接设置。": "Не удалось открыть интерфейс центрального узла. Локальные записи не затронуты. Проверьте адрес узла и сеть, затем повторите или откройте настройки подключения.",
  "验证采集连接只检查本设备的上传权限；中央资料仍需在中央界面单独登录。": "Проверка подключения сбора проверяет только доступ этого устройства к загрузке. Для чтения материалов центрального узла войдите отдельно.",
