  "跟随默认组合": "Использовать сценарии по умолчанию",
  "选择记忆策略": "Выбрать стратегии памяти",
  "默认组合": "Сценарии по умолчанию",
  "应用范围": "Применить к",
  "为新接收的来源资料选择记忆策略。多个策略可共用处理结果；保存设置不会重算历史资料，停用也不会删除已有记忆。": "Выберите стратегии памяти для новых поступающих материалов источников. Стратегии могут делиться результатами обработки. Сохранение не перерабатывает историю, а отключение сохраняет существующую память.",
  "自动 Memory 组合": "Автоматические сценарии памяти",
  "编码经验": "Опыт программирования",
  "个人记忆": "Личная память",
  "本地处理插件只能绑定本地服务": "Локальные плагины обработки требуют локальных служб",
  "此处理插件不支持自动摘要": "Этот плагин обработки не поддерживает автоматические сводки",
  "上传文件即可保存原件。普通文本直接收录；需要解释人物和结构的资料先预览再确认。": "Загрузите файлы, чтобы сохранить оригиналы. Обычный текст архивируется напрямую; содержимое, требующее указания авторства или интерпретации структуры, сначала показывается в предпросмотре для подтверждения.",
  "上传后保留原件。解析结果明确可靠且无歧义时自动保存，否则先预览并确认。": "Оригиналы сохраняются после загрузки. Ясные, надёжные и однозначные результаты сохраняются автоматически; остальные требуют предпросмотра и подтверждения.",
  "解析方式": "Способ разбора",
  "默认格式处理或模型解析": "Обработка формата по умолчанию или разбор моделью",
  "本地 Source Pack 使用已固定的解析程序；不接受临时解析说明。": "Локальные Source Pack используют закреплённый код разборщика и не принимают импровизированные инструкции разбора.",
  "明确可靠且无歧义的解析结果会自动保存；其余需要你确认。": "Ясные, надёжные и однозначные результаты разбора сохраняются автоматически; остальные требуют вашего подтверждения.",
  "自动发布": "Публикуется автоматически",
  "需要确认": "Требуется подтверждение",
  "保存原件并处理": "Сохранить оригиналы и обработать",
  "文件上传进度": "Ход загрузки файла",
  "新增变化达到门槛，或有新增资料且达到最大等待时间时运行。每分钟检查一次；进行中的窗口沿用启动时的设置。": "Запускается при достижении порога изменений или когда новое содержимое достигает максимального ожидания. Проверка каждую минуту; активные окна сохраняют настройки, действовавшие при запуске.",
  "最大等待（小时）": "Максимальное ожидание (часы)",
  "待办": "Задачи",
  "取消待办": "Отменить задачу",
  "标记完成": "Отметить выполненной",
  "重新打开": "Открыть заново",
  "无截止时间": "Без срока",
  "添加待办": "Добавить задачу",
  "截止时间（选填）": "Срок (необязательно)",
  "待办标题": "Название задачи",
  "待办可以没有截止时间；完成待办不会创建日历事件。": "У задач может не быть срока. Завершение задачи не создаёт событие календаря.",
  "；尚未安排记忆整理。": "; обработка памяти не запланирована.",
  "更多": "Ещё",
  "交互问答并发": "Параллелизм интерактивных запросов",
  "后台 Agent 并发": "Параллелизм фонового агента",
