  "保存设备名称": "Сохранить имя устройства",
  "设备名称已保存": "Имя устройства сохранено",
  "权限管理": "Разрешения",
  "屏幕录制、辅助功能、日历与文件访问": "Запись экрана, универсальный доступ, календари и файлы",
  "仅在使用对应功能时授权。从系统设置返回后会刷新状态。": "Предоставляйте доступ при использовании функции. Состояние обновляется при возврате из системных настроек.",
  "完整内容采集需要此权限；仅应用活动无需授权。": "Требуется для захвата содержимого экрана; активность приложений его не требует.",
  "读取通知中心当前可见内容需要此权限。": "Требуется для чтения видимого содержимого Центра уведомлений.",
  "连接和读取所选日历需要完整访问权限。": "Для подключения и чтения выбранных календарей требуется полный доступ.",
  "文件访问": "Доступ к файлам",
  "通过文件选择器授权所选路径；受保护目录可能需要完整磁盘访问。macOS 不提供可靠的全局状态查询。": "Выбирайте пути через диалог выбора файлов. Защищённые папки могут требовать полного доступа к диску. macOS не предоставляет надёжной проверки глобального состояния.",
  "按所选路径访问": "Доступ зависит от выбранного пути",
  "打开系统设置 ↗": "Открыть системные настройки ↗",
  "刷新权限状态": "Обновить разрешения",
  "截图去重": "Дедупликация снимков экрана",
  "关闭 · 保留每次采样": "Выкл. · сохранять каждый сэмпл",
  "跳过同应用连续完全相同的截图": "Пропускать подряд идущие одинаковые снимки одного приложения",
  "在隐私过滤后比较图片；不合并不同应用，不累计被跳过截图的使用时长。": "Изображения сравниваются после фильтрации конфиденциальности. Разные приложения не объединяются; пропущенные сэмплы не добавляют время использования.",
  "中央仓库将在 Chrome 打开，未安装时使用默认浏览器。请在浏览器中独立登录管理员账号；采集令牌不会传给浏览器。": "Архив откроется в Chrome, а при его отсутствии — в браузере по умолчанию. Войдите в браузере под учётной записью администратора; учётные данные сборщика браузеру не передаются.",
  "自定义 · 调整下方参数": "Пользовательский · настройте параметры ниже",
  "‹ 采集与存储": "‹ Захват и хранение",
  "屏幕录制尚未授权，请在权限管理中开启。": "Запись экрана не авторизована. Включите её в разделе «Разрешения».",
  "日历访问尚未授权，请在权限管理中开启。": "Доступ к календарю не авторизован. Включите его в разделе «Разрешения».",
  "读取通知需要辅助功能权限，请先授权后再启用。": "Для чтения уведомлений требуется доступ к универсальному доступу. Предоставьте его перед включением этой функции.",
  "权限检查失败，请重试。": "Не удалось проверить разрешения. Повторите попытку.",
  "权限状态读取失败，请重试。": "Не удалось прочитать состояние разрешений. Повторите попытку.",
  "重复截图已跳过": "Повторный снимок экрана пропущен",
  "当前平台不支持": "Не поддерживается на этой платформе",
  "无法确认，请检查系统设置": "Неизвестно; проверьте системные настройки",
  "不可用日历：{0}（可取消选择）": "Недоступный календарь: {0} (снимите выбор, чтобы удалить)",
