  "请在目标设备打开日程建议并同步。结果不明时只核实已有事件，避免重复创建。": "Откройте «Предлагаемые события» на целевом устройстве и синхронизируйте. Если результат неясен, проверяйте существующие события, чтобы избежать дубликатов.",
