  "同一设备、同一应用的连续截图归为一段；切换应用或相邻采样超过 5 分钟即分段。范围仅限所选日期，本机与中央按各自保留的记录分组。": "Последовательные снимки экрана с одного устройства и приложения образуют сессию. Смена приложения или пауза более 5 минут начинает новую сессию. Группы используют сохранённые записи в пределах выбранной даты.",
  "每 15 分钟按设备与应用汇集截图。": "Снимки экрана группируются по устройству и приложению в 15-минутных интервалах.",
  "起止时间表示观察范围，不代表持续使用时长。": "Время начала и конца показывает окно наблюдения, а не непрерывное использование.",
