  "二维码生成失败，可以复制或下载连接邀请 JSON。": "Не удалось создать QR-код. Вместо этого скопируйте или скачайте JSON приглашения.",
  "连接邀请已到期，请重新生成；已经连接的设备不受影响。": "Срок действия приглашения истёк. Создайте новое; подключённые устройства не затронуты.",
  "请求超时，请刷新连接列表确认结果后重试。": "Истекло время ожидания запроса. Обновите список подключений, чтобы проверить результат, затем повторите попытку.",
  "已复制，请只粘贴到你信任的客户端。": "Скопировано. Вставляйте только в доверенный клиент.",
  "当前环境无法访问剪贴板，请使用下载 JSON，或展开内容手动复制。": "Буфер обмена недоступен. Скачайте JSON или разверните содержимое и скопируйте вручную.",
  "邀请已取消，旧二维码和 JSON 不再有效。": "Приглашение отменено. Старые QR-код и JSON недействительны.",
  "连接凭据已撤销；归档资料保留，客户端队列不会被删除。": "Учётные данные отозваны. Архивные данные и очереди клиентов сохранены.",
  "设备二维码与连接授权": "Сопряжение устройств и доступ",
  "扫码或导入一次性邀请，把手机和电脑连接到中央节点。": "Отсканируйте или импортируйте одноразовое приглашение, чтобы подключить телефоны и компьютеры к центральному узлу.",
  "个有效连接": "активных подключений",
  "填写设备可访问的地址": "Укажите доступный адрес",
  "生成邀请或 MCP 配置": "Создайте приглашение или конфигурацию MCP",
  "在客户端确认并连接": "Подтвердите и подключитесь на клиенте",
  "本服务供设备访问的地址": "Адрес этого сервера для устройств",
  "邀请节点地址": "URL узла для приглашения",
  "填写指向本服务的 HTTPS 地址，供客户端配对和上传使用。二维码不会自动打通网络。": "Укажите доступный HTTPS-адрес этого сервера для сопряжения и загрузки. QR-код не создаёт сетевое подключение.",
  "连接名称": "Имя подключения",
  "我的 K90 Pro Max / 工作电脑 / Chatbot": "Мой K90 Pro Max / Рабочий компьютер / Чат-бот",
  "用于在下面的列表中识别和撤销连接。": "Позволяет найти и отозвать это подключение в списке ниже.",
  "当前是本机地址，手机扫码后会指向手机自己。跨设备连接请先填入可访问的 HTTPS 域名；本机地址可用于同一台电脑或明确配置了端口转发的开发环境。": "Это адрес loopback; телефон подключится сам к себе. Для другого устройства укажите доступный HTTPS-домен. Loopback подходит для того же компьютера или при явно настроенном пробросе портов.",
  "连接类型": "Тип подключения",
  "连接设备": "Подключить устройство",
  "连接 Chatbot": "Подключить чат-бота",
  "手机、Mac 与其他采集端": "Телефоны, Mac и другие сборщики",
  "每份邀请仅能使用一次，10 分钟后失效。连接后得到独立采集凭据，不包含中央管理令牌。": "Каждое приглашение можно использовать один раз; оно истекает через 10 минут. При сопряжении выдаются отдельные учётные данные сборщика без токена владельца центрального узла.",
  "设备身份": "Идентичность устройства",
  "邀请设备身份": "Идентичность устройства для приглашения",
  "首次连接的新设备": "Новое устройство",
  "从旧版手填令牌迁移或重新配对，请选择原设备以保留身份。成功配对后会替换该设备之前的采集凭据。": "При повторном сопряжении выберите исходное устройство, чтобы сохранить его идентичность. Успешное сопряжение заменит прежние учётные данные.",
  "正在生成…": "Создание…",
  "重新生成二维码": "Создать QR-код заново",
  "生成设备二维码": "Создать QR-код устройства",
  "连接其他 Chatbot · MCP": "Подключение других чат-ботов · MCP",
  "生成标准 HTTP MCP 连接 JSON，粘贴到支持 URL 与 Bearer 请求头的客户端。": "Создаёт стандартный JSON подключения MCP по HTTP для клиентов, поддерживающих URL и заголовки Bearer.",
  "访问权限": "Доступ",
  "MCP 访问权限": "Доступ MCP",
