  "仅写入指定来源": "Запись только в выбранные источники",
  "尚未启用 MCP。请在设置 → 来源与外部应用中开启 MCP，并配置独立读令牌后重启；写入还需明确启用并设置允许的信源。": "MCP отключён. Включите его в «Настройки → Источники и внешние приложения», задайте отдельный токен чтения и перезапустите. Запись также требует явного включения и разрешённых источников.",
  "未配置": "Не настроено",
