  "只读权限能检索归档中的个人资料，请只交给你信任的应用。": "Доступ на чтение позволяет искать личные данные в архиве. Передавайте только доверенным приложениям.",
  "只接受 OAuth 的客户端暂不能直接使用此 JSON。": "Клиенты, поддерживающие только OAuth, пока не могут использовать этот JSON напрямую.",
