  "有效期内，持有邀请的人可以领取该连接。请勿公开分享；关闭此页面不会取消邀请，需使用下面的取消按钮。": "Любой, у кого есть действующее приглашение, может его использовать. Не делитесь им публично. Закрытие страницы не отменяет приглашение — используйте кнопку отмены ниже.",
