  "已达到预览上限，请缩小来源或类型范围。": "Достигнут лимит предпросмотра. Сузьте фильтр по источнику или типу.",
  "重新处理将生成新的派生结果，已有校正会标为过期，原件继续保留。": "Повторная обработка создаст новые производные результаты и пометит существующие исправления устаревшими. Оригиналы сохраняются.",
