  "标签为匿名声纹分组。请试听后自行填写名称；不确定或重叠片段需要回听。": "Метки обозначают анонимные голосовые группы. Прослушайте перед именованием; неуверенные или перекрывающиеся фрагменты нужно переслушать.",
