  "模型只提出建议，确认后生成单独的校正版；未校正原文始终保留。本地多人录音使用已配置的本地语言模型。": "Модель только предлагает изменения. Подтверждение создаёт отдельную исправленную версию; исходный текст всегда сохраняется. Локальная запись с несколькими говорящими использует настроенную локальную модель.",
