  "一次最多选择 2,000 个文件。较多文件可以打包为 ZIP 或使用服务器目录。": "Можно выбрать до 2 000 файлов за раз. Для большего объёма используйте ZIP-архив или каталог на сервере.",
  "单个上传文件不能超过 64 MB，请拆分文件后导入。": "Каждый загружаемый файл — не более 64 МБ. Разделите большие файлы перед импортом.",
  "一次上传的文件总量不能超过 256 MB，请分批导入。": "Общий объём одной загрузки — не более 256 МБ. Импортируйте партиями.",
