  "这是运行 Mote 中央节点的机器上的路径。节点会复制可读取的文件到归档。": "Путь на машине, где работает ваш центральный узел. Доступные для чтения файлы будут скопированы в архив.",
  "资料名称": "Название материала",
  "选填": "Необязательно",
  "例如：过去一年的随手记": "Например: быстрые заметки за прошлый год",
  "告诉 Mote 如何理解这份资料": "Расскажите Mote, как понимать этот материал",
  "格式、作者与归属说明": "Указания по формату, авторству и принадлежности",
  "格式按所选 Source Pack 解析；说明用于资料背景和归属范围。": "Формат разбирается выбранным Source Pack. Указания задают контекст материала и область принадлежности.",
  "例如：这是我的日记，引用和 AI 回复属于原说话人。时间是北京时间；每篇日记独立保存。": "Например: это мои дневниковые записи. Цитаты и ответы ИИ принадлежат их исходным авторам. Время — пекинское; сохраняйте каждую запись отдельно.",
  "可一次说明格式、时间、作者，以及哪些内容属于你。模型按说明范围理解，第三方和 AI 引用保留原角色。": "Опишите в одном месте формат, время, авторов и какое содержимое принадлежит вам. Модель следует указанной области и сохраняет исходные роли цитат третьих лиц и ИИ.",
  "未填写也会保留原件，可检索已提取的正文；身份未知时，可保存有用的来源限定观察。": "Без указаний оригиналы всё равно сохраняются, а извлечённый текст доступен для поиска. Если авторство неизвестно, полезные наблюдения сохраняются с привязкой к источнику.",
  "本次导入说明": "Указания для этого импорта",
  "说明按文字中的范围用于理解这次导入的资料，不会把第三方和 AI 引用整批变成你的表达。": "Указания применяются в заявленной области к материалам этого импорта. Цитаты третьих лиц и ИИ не становятся вашими высказываниями во всей партии.",
  "例如：这是我的聊天导出，张三是我。时间是北京时间；每段对话独立保存，保留消息的时间和附件关系。": "Например: это экспорт моего чата, Чжан Сан — это я. Время — пекинское. Сохраняйте каждый диалог отдельно, сохраняя время сообщений и связи с вложениями.",
  "可以说明人物、时间、格式和需要保留的细节。含糊之处会出现在预览中。": "Укажите людей, время, формат и детали, которые нужно сохранить. Неясности будут видны в предпросмотре.",
  "先保存原件，解析完成后由你确认。": "Сначала сохраняются оригиналы. Подтвердите после разбора.",
