  "这是应用公开的状态。媒体采集在客户端单独开启；通知使用权用于发现媒体会话，不保存通知正文或音频。音乐、有声书等内容类型由分析时结合证据判断。": "Это состояние публикует приложение. Сбор медиа включается отдельно на клиенте. Доступ к уведомлениям обнаруживает медиасессии, не сохраняя тексты уведомлений или аудио. Типы контента (музыка, аудиокниги) определяются по доказательствам при анализе.",
