  "媒体播放与前台应用使用分别计时，可能同时发生，不应相加。只累计独立媒体记录的播放采样区间；同一设备重叠区间合并，多台设备分别累计。应用或状态分组可能重叠。": "Воспроизведение медиа и использование приложений на переднем плане измеряются отдельно и могут пересекаться — их нельзя складывать. Учитываются только независимые интервалы выборки воспроизведения; пересечения на одном устройстве объединяются, разные устройства суммируются отдельно. Группы по приложениям или состояниям могут пересекаться.",
  "截图附带的媒体状态不重复计时。暂停、缓冲和观察空隙不补齐；播放进度或媒体总长度不等于收听时长，远程播放也不代表手机发声。": "Состояние медиа из скриншотов повторно не учитывается. Паузы, буферизация и пропуски наблюдений не восполняются; позиция воспроизведения и длительность медиа не равны времени прослушивания, а удалённое воспроизведение не означает звук с телефона.",
