  "记忆以文本保存，按“概览 → 内容与边界 → 原始证据”逐层展开，全文索引可从文本重建。自动生成的长期记忆需要你确认。高频上传建议保留较长周期和每轮上限。": "Память хранится в виде текста и раскрывается по уровням: обзор → содержимое и границы → исходные доказательства. Полнотекстовый индекс можно перестроить из текста. Автоматически созданная долговременная память требует вашего подтверждения. При частых загрузках используйте более длинные интервалы и ограниченные пакеты.",
