  "仅显示上报时可获取的字段。状态是当时的观察值；缺失不代表否或零。": "Показаны только поля, доступные на момент отправки. Значения описывают наблюдения на тот момент; отсутствие не означает «нет» или ноль.",
  "原始系统事件，不表示你已阅读通知或正在执行某项任务。熄屏不等于锁定；服务中断期间不补造事件。系统可能隐藏敏感通知。": "Необработанные системные события не доказывают, что вы прочитали уведомление или выполняли задачу. Выключенный экран не означает блокировку. Пропуски не восстанавливаются; система может скрывать чувствительные уведомления.",
  "文件访问时间也可能由同步程序或其他进程读取更新，不能据此断定你查看过文件。": "Время доступа к файлу могут обновить программы синхронизации или другие процессы — оно не доказывает, что вы открывали файл.",
  "这是完整扫描发现来源消失的时间，无法确认实际删除时刻或原因，也可能是移动或重命名。": "Полное сканирование обнаружило исчезновение в это время; нельзя установить момент и причину удаления. Файл мог быть перемещён или переименован.",
