  "刷新模型列表": "Обновить список моделей",
  "目录暂无可用模型，可手动填写。": "В каталоге нет моделей. Введите вручную.",
  "目录使用中央节点本机 Codex 的登录账户。选择只填写模型 ID；实际请求仍使用本页配置的 API 协议与凭据。": "Используется локальная учётная запись Codex центрального узла. Выбор заполняет только ID модели; запросы по-прежнему используют протокол и учётные данные, настроенные на этой странице.",
  "根据当前地址和凭据自动加载；目录可见不代表支持工具调用，可使用下方测试连接验证。": "Загружается по текущему адресу и учётным данным. Видимость каталога не гарантирует поддержку вызова инструментов; проверьте подключением ниже.",
