  "只保留在当前页面内存，保存后清空输入。": "Хранится только в памяти страницы; поле очищается после сохранения.",
  "推理强度": "Интенсивность рассуждений",
  "选择“由模型决定”兼容更多模型；具体能力取决于所选模型。": "«На усмотрение модели» поддерживает больше моделей; возможности зависят от выбранной модели.",
  "最长等待时间（秒）": "Максимальное ожидание (секунды)",
  "5–600 秒，适用于模型请求。": "5–600 секунд для запросов модели.",
