  "Agent 总运行超时": "Общий тайм-аут выполнения агента",
  "单次模型请求超时须为 5–600 秒。": "Тайм-аут одного запроса модели должен быть 5–600 секунд.",
  "Agent 总运行超时须为 5–3600 秒。": "Общий тайм-аут агента должен быть 5–3600 секунд.",
  "Agent 总运行超时须为空，或为 5–3600 秒。": "Общий тайм-аут агента должен быть пустым или 5–3600 секунд.",
  "5–600 秒；只限制一次 Provider API 请求，不包含后续工具循环。": "5–600 секунд; ограничивает только один запрос Provider API, без последующих циклов инструментов.",
  "可留空；限制从 Agent 开始到结束的整个运行周期，包含多次模型请求和工具调用。": "Необязательно; ограничивает весь запуск агента от начала до конца, включая несколько запросов модели и вызовы инструментов.",
  "5–3600 秒；限制一次 Agent 从开始到完成的整个运行周期。": "5–3600 секунд; ограничивает весь запуск агента от начала до завершения.",
  "输出上限 / 超时": "Лимит вывода / Тайм-ауты",
