  "常用默认 65,536；选择支持当前预算的模型。": "По умолчанию 65 536. Выберите модель, поддерживающую этот бюджет.",
  "最大输出 token 数": "Максимум выходных токенов",
  "输出 token 上限": "Лимит выходных токенов",
  "1–128000。单次响应的上限，包含正文、HTML 及服务商计入的推理 token，不是固定生成长度、字数或图片大小。保存后生效。": "1–128000. Лимит на один ответ, включая текст, HTML и учитываемые провайдером токены рассуждений. Это не фиксированная длина ответа, число слов или размер изображения. Применяется при сохранении.",
  "允许本机模型免密访问": "Разрешить локальные модели без аутентификации",
  "只适用于回环地址；容器中的“本机”指容器本身。": "Только для loopback-адресов; внутри контейнера «локальный» означает сам контейнер.",
  "自定义请求头操作": "Действие с пользовательскими заголовками",
