  "名称与值均为字符串；整体替换。已有值不会读取或回显。": "Имена и значения — строки; заменяется целиком. Существующие значения не читаются и не отображаются.",
  "高级请求参数操作": "Действие с дополнительными параметрами",
  "高级请求参数 JSON": "JSON дополнительных параметров",
  "按当前协议填写 JSON 对象，整体替换。消息、工具与其他运行必需字段由 Mote 管理；已有值不会回显。": "Введите JSON-объект по текущему протоколу; заменяется целиком. Сообщения, инструменты и обязательные поля управляются Mote; существующие значения скрыты.",
  "允许在更改后的服务地址复用已保存的凭据": "Разрешить сохранённые учётные данные по изменённому адресу сервиса",
  "这会把保留的 API key、请求头或高级参数发送到当前填写的地址。也可以改为填写新值或清除旧值。": "Сохранённые API-ключи, заголовки или дополнительные параметры будут отправлены по введённому адресу. Можно также ввести новые значения или очистить старые.",
  "测试连接会由中央节点发送少量合成内容，最多等待 30 秒，可能产生少量费用；不会读取资料库。测试不会保存草稿。": "При проверке центральный узел отправляет небольшой синтетический запрос, ждёт до 30 секунд, возможны небольшие расходы; архив не читается. Проверка не сохраняет черновик.",
  "（{0} 秒）": "({0} с)",
  "；保存后才会应用草稿。": "; черновик применится после сохранения.",
  "有未保存的修改，仅保留在当前页面": "Есть несохранённые изменения только на этой странице",
  "当前没有未保存的修改": "Нет несохранённых изменений",
