  "来自页面保存的配置；重启中央节点后仍然保留。": "Сохранено на этой странице; сохраняется после перезапуска центрального узла.",
  "来自中央节点的启动环境或部署配置。": "Из стартового окружения или конфигурации развёртывания центрального узла.",
