  "高级请求参数": "Дополнительные параметры",
  "恢复部署配置": "Восстановить настройки развёртывания",
  "删除本页保存的模型配置，立即重新使用中央节点的启动环境或部署配置。当前未保存的草稿也会清空；不会修改部署文件。": "Удаляет сохранённые здесь настройки модели и немедленно восстанавливает стартовые или развёртываемые настройки. Несохранённые черновики очищаются. Файлы развёртывания не изменяются.",
  "正在恢复…": "Восстановление…",
  "确认恢复部署配置": "Подтвердить восстановление настроек развёртывания",
  "随手记已同步到你的中央节点。": "Быстрая заметка синхронизирована с вашим центральным узлом.",
  "本机存储不可用或已满；草稿目前只在此窗口，请先复制保存。": "Локальное хранилище недоступно или переполнено. Черновик существует только в этом окне — сначала скопируйте его.",
  "Mote 随手记": "Быстрая заметка Mote",
  "已保存到本机待同步队列，联网后会继续同步。": "Сохранено в локальную очередь. Синхронизация продолжится при подключении.",
  "移除这条本机待同步副本？若中央节点已收到但确认丢失，需要在下方历史记录中另行删除。": "Удалить эту ожидающую локальную копию? Если узел получил её, но подтверждение потерялось, удалите архивную запись отдельно ниже.",
  "想到什么，就记下来。": "Записывайте, что приходит в голову.",
  "心情、杂事、一个还没成形的想法，都可以成为上下文。": "Настроение, мелкие дела и неоформленные идеи — всё может стать контекстом.",
  "此刻想留下什么？": "Что вы хотите сохранить?",
  "记下此刻的想法…": "Запишите свои мысли…",
  "我的心情": "Моё настроение",
  "可选，由你自己描述": "Необязательно, своими словами",
  "比如：松了一口气": "Например: облегчение",
