  "保存并同步": "Сохранить и синхронизировать",
  "草稿和待同步内容保存在此应用的本机存储中，清除应用数据会移除它们。打开随手记时自动续传；按中央节点地址分别保存。": "Черновики и ожидающие заметки хранятся локально для каждого адреса центрального узла. Очистка данных приложения удалит их. Синхронизация возобновляется при открытии быстрых заметок.",
  "待同步 ·": "Ожидает синхронизации ·",
  "正在同步": "Синхронизация",
