  "关于 Mote": "О Mote",
  "软件版本、更新与部署信息": "Версия, обновления и сведения о развёртывании",
  "开发者选项": "Параметры разработчика",
  "诊断、日志与高级生效配置": "Диагностика, журналы и расширенные активные настройки",
  "模型与记忆设置可直接保存并生效；其他偏好通过部署草稿修改并重启。离开设置页面或返回上级菜单时，未保存的输入会丢弃。": "Настройки модели и памяти применяются при сохранении. Другие предпочтения используют черновик развёртывания и перезапуск. Несохранённые данные сбрасываются при выходе из настроек или возврате в родительское меню.",
  "来自运行中的中央节点；与上方尚未应用的草稿分开显示。": "От работающего центрального узла; отображается отдельно от неприменённого черновика выше.",
