  "点击检查后连接 GitHub，不上传个人资料或中央令牌。": "Проверка подключается к GitHub без отправки личных данных или центральных токенов.",
  "此渠道暂时没有可用的签名发布版本。": "В этом канале пока нет подписанных релизов.",
  "更新检查未通过，现有程序和设置保持原样；稍后可重试。": "Проверка обновлений не удалась. Программа и настройки не изменены. Повторите позже.",
  "发现 {0}，发布签名已验证。": "Найдена {0}; подпись релиза проверена.",
