  "查看版本说明与安装包": "Открыть примечания к выпуску и загрузки",
  "上次检查：": "Последняя проверка:",
  "在部署机的 Mote 目录执行。命令先校验下载并准备程序，再备份、切换和检查健康状态。新版启动失败时保留快照，使用回退命令恢复。": "Выполните в каталоге Mote на машине развёртывания. Команда проверяет и подготавливает загрузку, затем создаёт резервную копию, переключает и проверяет работоспособность. Если запуск новой версии не удался, восстановите сохранённый снимок командой отката.",
  "需要回退时": "Для отката",
  "回退恢复升级前的数据快照；升级后的资料会另行保留。不要直接用旧程序打开已升级的数据。": "Откат восстанавливает снимок данных до обновления; новые данные сохраняются отдельно. Не открывайте обновлённые данные старой программой.",
  "此节点未由命名部署环境管理。请先按部署文档建立对应环境，再使用更新命令；本页面不会直接重启当前服务。": "Этот узел не управляется именованным профилем развёртывания. Создайте его по руководству развёртывания перед использованием команд обновления. Эта страница не перезапускает сервис.",
