  "由中央节点定时同步你选定的日历，只申请读取权限。取消连接会移除本机授权，历史资料仍保留。": "Центральный узел периодически синхронизирует выбранные календари с доступом только для чтения. Отключение удаляет локальную авторизацию, но сохраняет историю.",
