  "此设备或记录没有上报媒体状态，无法判断当时是否有音频播放。": "Это устройство или запись не сообщили состояние мультимедиа; воспроизводился ли тогда звук — неизвестно.",
  "媒体采集已关闭": "Сбор мультимедиа отключён",
  "当时没有启用媒体采集，无法判断是否有音频播放。": "Сбор мультимедиа был отключён; воспроизводился ли тогда звук — неизвестно.",
  "媒体采集等待授权": "Сбор мультимедиа ожидает авторизации",
  "请在 Android 客户端开启媒体采集，并在系统设置授权通知使用权，以读取应用公开的媒体会话。": "Включите сбор мультимедиа на Android и предоставьте доступ к уведомлениям в системных настройках, чтобы читать публичные сеансы мультимедиа.",
  "媒体状态不可用": "Состояние мультимедиа недоступно",
  "系统当时未能提供媒体状态，不能据此认定没有音频播放。": "Система не смогла предоставить состояние мультимедиа; это не означает, что звук не воспроизводился.",
  "未观察到媒体会话": "Сеансы мультимедиа не обнаружены",
  "这次观察没有发现可见的媒体会话；未公开媒体会话的应用可能无法被记录。": "При этом наблюдении видимых сеансов мультимедиа не было. Приложения, не публикующие сеансы мультимедиа, могут не записываться.",
  " · {0} 个会话": " · сеансов: {0}",
  "正在播放{0}": "Воспроизводится {0}",
  "{0} 个媒体会话": "Сеансов мультимедиа: {0}",
  "应用通过系统公开的媒体状态；播放状态不代表你实际收听或专注。": "Публикуемое приложением состояние мультимедиа не подтверждает фактическое прослушивание или внимание.",
  "应用通过系统公开的媒体状态，不包含音频录制或语音转写。播放时长只累计已观察到的播放区间；暂停、未授权和采样空隙不会补齐，也不能据此确定你实际收听。": "Публикуемое приложением состояние мультимедиа исключает запись аудио и транскрипцию. Длительность учитывает только наблюдаемые интервалы воспроизведения; паузы, отсутствие разрешения и пропуски выборки не заполняются. Это не доказывает фактическое прослушивание.",
  "{0}须为有效的 JSON 对象。": "{0}: требуется допустимый объект JSON.",
  "{0}须为 JSON 对象，不能是数组或空值。": "{0}: требуется объект JSON, а не массив или null.",
  "模型服务地址须为完整的 HTTP(S) 地址。": "URL службы модели должен быть полным HTTP(S)-адресом.",
  "模型服务地址不能含凭据、查询参数或片段。": "URL модели не может содержать учётные данные, параметры запроса или фрагменты.",
  "远程模型服务须使用 HTTPS；本机回环地址可使用 HTTP。": "Удалённые модели требуют HTTPS; службы на адресах loopback могут использовать HTTP.",
  "免密访问仅适用于本机回环地址。": "Доступ без аутентификации ограничен адресами loopback.",
  "输出 token 上限须为 1–128000 之间的整数。": "Лимит выходных токенов должен быть целым числом от 1 до 128000.",
  "最长等待时间须为 5–600 秒。": "Время ожидания должно быть 5–600 с.",
  "Codex Server 不暴露内部单次模型生成请求，此项不适用。": "Codex Server не раскрывает внутренние одиночные запросы на генерацию модели; этот параметр неприменим.",
  "服务或地址已改变。请填写新凭据、清除旧凭据，或明确允许在新地址复用。": "Служба или URL изменились. Замените или очистите учётные данные либо явно разрешите повторное использование.",
  "请填写新 API key，或选择清除已有密钥。": "Введите новый ключ API или выберите очистку сохранённого ключа.",
  "API key 不能包含换行或控制字符。": "Ключи API не могут содержать переводы строк или управляющие символы.",
  "请求头名称须为合法 HTTP 字段，值须为不含换行的字符串。": "Имена заголовков должны быть допустимыми полями HTTP; значения — строками без переводов строк.",
  "本机草稿无法读取；原数据已保留。": "Не удаётся прочитать локальный черновик; исходные данные сохранены.",
  "本机待同步随手记存在损坏记录；原数据已保留，不能覆盖。": "В ожидающих синхронизации локальных заметках есть повреждённые записи. Оригиналы сохранены; перезапись заблокирована.",
  "随手记 ID 已用于另一条内容。": "Этот ID заметки уже используется другим содержимым.",
  "本机随手记待同步空间已满，请先同步或导出待传内容。": "Локальная очередь заметок заполнена. Сначала синхронизируйте или экспортируйте ожидающие заметки.",
  "中央节点确认的随手记 ID 不匹配；本机记录已保留。": "Подтверждение центрального узла содержит другой ID заметки. Локальная запись сохранена.",
  "采集级别必须是完整内容、仅应用活动或不记录": "Уровень сбора должен быть: полное содержимое, только активность приложения или исключено",
  "应用采集规则必须为有效列表，最多 500 项": "Правила сбора приложений должны быть корректным списком не более чем из 500 элементов",
