  "来源待同步队列已满，请恢复网络后重试": "Очередь источника заполнена. Восстановите соединение и повторите.",
  "来源同步状态超过本地队列上限，请恢复网络后重试": "Состояние синхронизации источника превышает лимит локальной очереди. Восстановите соединение и повторите.",
  "中央批量来源确认不完整，已保留待重试版本": "Пакетное подтверждение источника центральным узлом было неполным. Версии сохранены для повтора.",
