  "无法打开 GitHub，请检查默认浏览器后重试。": "Не удаётся открыть GitHub. Проверьте браузер по умолчанию и повторите.",
  "中央界面加载失败，请确认中央节点正在运行且提供前端页面": "Не удалось загрузить центральный интерфейс. Проверьте, что узел работает и обслуживает веб-приложение.",
