  "正在结束上一轮采集，请稍后再试": "Завершение предыдущего захвата. Повторите вскоре.",
  "此 MVP 只支持 macOS 采集；Windows/Linux 需要接入可靠前台应用识别后才可启用": "Этот MVP поддерживает сбор только на macOS. Windows/Linux требуют надёжного определения активного приложения.",
  "已开启；按应用级别记录，完整内容先经过本地隐私过滤": "Включено; используются уровни сбора по приложениям, полное содержимое проходит локальную фильтрацию конфиденциальности",
  "采集已停止；本地记录保留，同步按设置独立运行": "Сбор остановлен. Локальные записи сохранены; синхронизация работает отдельно по настройкам.",
