  "已达到空闲阈值，暂停采集；操作电脑后恢复": "Достигнут порог бездействия; сбор возобновится, когда вы начнёте пользоваться компьютером",
  "无法确认电量，按你启用的电量策略暂停": "Состояние батареи неизвестно; приостановлено согласно вашей политике питания",
