  "屏幕已锁定，暂停记录": "Экран заблокирован; запись приостановлена",
  "仅记录应用活动；未采集屏幕、窗口标题或正文": "Только активность приложений; экран, заголовки окон и текст не собираются",
  "完整内容需要屏幕录制授权；仅活动应用仍可采样。请打开系统权限设置": "Для полного содержимого требуется разрешение на запись экрана. Выборка только активности остаётся доступной. Откройте системные настройки разрешений.",
  "本地千问视觉审查不可用，完整内容已跳过": "Локальная визуальная проверка Qwen недоступна; полное содержимое пропущено",
