  "设备标识无效": "Недопустимый ID устройства",
  "系统密钥存储不可用，无法解密令牌": "Системное хранилище ключей недоступно; не удаётся расшифровать токен",
  "无法读取配置：请检查系统密钥存储或备份后修复配置文件": "Не удаётся прочитать конфигурацию. Проверьте системное хранилище ключей или сделайте резервную копию и восстановите файл конфигурации.",
  "系统加密存储不可用，拒绝保存明文令牌": "Системное зашифрованное хранилище недоступно; токен в открытом виде не сохраняется",
  "本地记录的节点绑定信息无效": "Недопустимая привязка узла для локальных записей",
  "本地待上传记录已绑定原节点或凭据，不能重新归属；请恢复原连接完成同步": "Ожидающие записи привязаны к исходному узлу или учётным данным. Восстановите это подключение для синхронизации; перепривязка заблокирована.",
  "中央确认格式无效，原连接保持不变": "Недопустимое центральное подтверждение; исходное подключение не изменено",
