  "邀请无效、已使用或已过期，请在中央重新生成": "Приглашение недействительно, использовано или истекло. Создайте новое в центральном узле.",
  "中央拒绝此凭据，可能已撤销；原连接未修改": "Центральный узел отклонил эти учётные данные, возможно отозванные. Исходное подключение не изменено.",
  "此中央暂不支持连接邀请或连接检查，请升级中央，或使用手动连接": "Этот узел не поддерживает приглашения и проверку подключения. Обновите его или подключитесь вручную.",
