  "服务类型与处理插件不匹配": "Тип сервиса не соответствует плагину обработки",
  "分析步骤需要语言模型服务": "Для анализа нужен сервис языковой модели",
  "本地多人录音仅使用本地服务，自动摘要请另行配置处理插件": "Локальная запись с несколькими говорящими использует только локальные сервисы. Автоматические сводки настройте отдельным плагином обработки.",
  "插件不支持参数 {0}": "Плагин не поддерживает параметр {0}",
  "参数 {0} 的值不合法": "Недопустимое значение параметра {0}",
  "方案「{0}」不支持类型 {1}": "План «{0}» не поддерживает тип {1}",
  "文件使用的服务已变更；请明确重新处理文件以应用新方案": "Сервис файла изменился. Явно повторите обработку файла, чтобы применить новый план.",
  "请为方案选择处理服务": "Выберите сервис обработки для этого плана",
