  "{0} · 当天 {1} 条 · {2} 个{3} · 第 {4} 页": "{0} · записей за день: {1} · {2} {3} · Страница {4}",
  "同应用连续采样归为一段；切换应用或间隔超过 5 分钟分段。仅按本页日期与现存截图分组，起止范围不代表使用时长。": "Непрерывные образцы одного приложения образуют сессию; смена приложения или пауза более 5 минут начинает новую. Группы используют существующие снимки за эту дату. Диапазоны времени не показывают длительность использования.",
