  "正在读取详情…": "Загрузка деталей…",
  "本机记录已同步并清理，请切换到中央归档查看": "Локальная запись синхронизирована и очищена. Смотрите её в центральном архиве.",
  "记录已读取，正在加载图片…": "Запись загружена; загрузка изображения…",
  "原始系统事件 · 不代表已阅读通知或实际执行某项任务。熄屏不等于锁定。": "Исходное системное событие · Не доказывает прочтение уведомления или выполнение задачи. Погасший экран не означает блокировку.",
  "此记录的已观察播放时长：{0} 秒（不含观测缺口）": "Наблюдаемое воспроизведение в этой записи: {0} секунд (без пробелов наблюдения)",
