  "应用活动 · {0} 毫秒": "Активность приложения · {0} мс",
  "同步需要处理：{0}": "Синхронизация требует внимания: {0}",
  "采集图片": "Захваченное изображение",
  "图片暂不可用。": "Изображение временно недоступно.",
  "识别文字": "Распознанный текст",
  "此图片未识别到文字。": "На этом изображении текст не распознан.",
  "暂无识别文字。": "Распознанного текста пока нет.",
  "记录读取失败，请刷新重试": "Не удаётся прочитать запись. Обновите и повторите.",
  "中央记录暂不可读取，请检查网络后重试": "Не удаётся прочитать центральную запись. Проверьте сеть и повторите.",
  "本机记录暂不可读取，请刷新重试；文件已保留": "Не удаётся прочитать локальную запись. Обновите и повторите; файл сохранён.",
  "采集状态": "Состояние сбора",
  "屏幕：{0}": "Экран: {0}",
  "媒体：{0}": "Медиа: {0}",
  "Mote · 采集状态": "Mote · Состояние сбора",
  "你已停止采集，已有记录保留，同步按所选策略运行": "Вы остановили сбор. Записи сохранены; синхронизация выполняется по выбранной политике.",
  "同步与恢复": "Синхронизация и восстановление",
  "手机负责采集，中央端负责归档。已上传的本机副本按保留时间清理。": "Телефон собирает данные; центральный узел архивирует. Загруженные локальные копии удаляются по истечении срока хранения.",
  "正在读取本机同步状态…": "Загрузка локального состояния синхронизации…",
  "查看待上传队列": "Просмотреть очередь ожидания",
  "立即同步待发记录": "Синхронизировать ожидающие записи сейчас",
  "从未确认的记录继续发送；上传中断只重发未确认记录。同一条记录重试不会生成重复副本。仍遵守 Wi-Fi 设置。": "Продолжает с неподтверждённых записей. Прерванные загрузки повторно отправляют только эти записи, не создавая дубликатов. Настройки Wi-Fi по-прежнему действуют.",
  "检查两端记录状态": "Проверить записи на обеих сторонах",
  "只检查手机仍保留的采集记录在中央端是否可见；不会把“中央存在”直接当作上传确认，也不会删除或恢复记录。": "Проверяет, видны ли на центральном узле записи, ещё хранящиеся на телефоне. Наличие на узле не считается подтверждением загрузки; ничего не удаляется и не восстанавливается.",
  "全量补传 · 本机保留的记录": "Повторно отправить все сохранённые локальные записи",
  "重新上传本机保留的数据？": "Повторно загрузить сохранённые локальные данные?",
  "会重发本机仍保留的截图、OCR 原始事件、通知、设备事件、笔记及已启用来源的保留版本。中央端核验相同 ID 去重，继续补齐缺失数据。\n\n已从手机清理的数据无法补传。中央已删除或内容冲突的记录不会覆盖或恢复，暂停的来源不会启用。此操作可能产生较多流量，仍遵守网络设置。": "Повторно отправляет сохранённые снимки экрана, исходные события OCR, уведомления, события устройства, заметки и сохранённые версии из включённых источников. Проверки ID на узле устраняют дубликаты и заполняют пробелы.\n\nДанные, уже очищенные с телефона, нельзя отправить повторно. Удалённые на узле или конфликтующие записи не перезаписываются и не восстанавливаются; приостановленные источники остаются приостановленными. Это может потребовать значительного трафика; сетевые настройки по-прежнему действуют.",
  "开始补传": "Начать повторную отправку",
  "尚未执行检查或全量补传": "Проверка или полная повторная отправка ещё не выполнялись",
  "停止本次检查 / 准备补传": "Остановить эту проверку / подготовку повторной отправки",
  "已请求停止检查；已进入待发队列的记录按同步策略保留": "Запрошена остановка. Записи, уже поставленные в очередь, сохраняются согласно политике синхронизации.",
  "查看记录与冲突": "Просмотреть записи и конфликты",
  "查看来源同步状态": "Просмотреть состояние синхронизации источников",
  "需要处理时：\n• 网络或服务暂不可用：自动模式退避重试，手动模式再次点同步。\n• 授权失效：重新连接同一节点后同步。\n• 同 ID 内容冲突 / 中央已删除：保留本机副本，跳过该条继续其他记录，不自动覆盖。\n• 等待 OCR：图片已归档不代表识别完成，识别结果会另行确认。\n\n中央端显示的是上次联系时的状态，不是手机实时状态。": "Когда требуется внимание:\n• Сеть или служба недоступны: автоматический режим повторяет с паузами; в ручном режиме нужно ещё раз нажать синхронизацию.\n• Авторизация истекла: переподключите тот же узел, затем синхронизируйте.\n• Конфликт ID / удаление на узле: локальная копия сохраняется, остальные записи продолжаются без перезаписи.\n• Ожидание OCR: заархивированные изображения не доказывают завершения распознавания; результаты подтверждаются отдельно.\n\nСтатус узла отражает последний контакт, а не текущее состояние телефона.",
  "请先配置连接": "Сначала настройте подключение",
  "正在读取存储状态": "Чтение состояния хранилища",
  "{0}\n本机保留 {1} 条 · 待发 {2} 条\n需处理 {3} 条 · 等待 OCR {4} 张\n来源待发 {5} 个版本 / {6} 项设置\n\n{7}\n最后收到上传确认：{8}": "{0}\nЛокально хранится: {1} · Ожидают: {2}\nТребуют внимания: {3} · Ожидают OCR: {4}\nИсточники ожидают: {5} версий / {6} настроек\n\n{7}\nПоследнее подтверждение загрузки: {8}",
  "请检查存储": "Проверьте хранилище",
