  "已保存设置发生变化，页面已更新；请检查后重新保存": "Сохранённые настройки изменились; страница обновлена. Проверьте и сохраните снова.",
  "设置保存与恢复均未持久完成，采集已停止；请检查存储空间并重试": "Ни сохранение, ни восстановление не смогли записать настройки. Сбор остановлен; проверьте хранилище и повторите.",
  "连接设置未能持久恢复，采集已停止；原连接恢复资料仍保留": "Не удалось сохранить восстановление подключения. Сбор остановлен; исходные данные восстановления сохранены.",
  "待同步资料属于原节点，请先同步到原节点；清空连接不会解除资料绑定": "Ожидающие данные принадлежат исходному узлу. Сначала синхронизируйтесь с ним; очистка подключения не снимает привязку.",
