  "旧存储副本清理未完成": "Очистка старого хранилища не завершена",
  "当前连接没有查看此记录的权限，请检查连接凭据": "Подключение не имеет доступа к этой записи. Проверьте учётные данные.",
  "此记录已不存在，或中央节点版本尚不支持浏览": "Запись отсутствует или версия узла не поддерживает просмотр",
