  "输出未知": "Вывод неизвестен",
  " · 等待充电": " · Ожидание зарядки",
  "OCR 待处理{0}": "Ожидание OCR{0}",
  "OCR 状态未知（历史记录）": "OCR неизвестен (историческая запись)",
  "连接或同步策略已变化，本次操作已停止；请重新发起": "Подключение или политика синхронизации изменились. Операция остановлена; начните заново.",
  "正在准备全量补传…": "Подготовка полной повторной отправки…",
  "已安排补传 {0} 条本机采集记录及 {1} 个保留来源版本；实际上传进度见下方同步状态。冲突和中央已删除记录保持隔离。": "В очередь на повторную отправку добавлены {0} локальных записей захвата и {1} сохранённых версий источников. Фактический ход загрузки см. в статусе синхронизации ниже. Конфликты и удалённые на узле записи остаются изолированными.",
  "检查完成：中央可见 {0} 条，不可见 {1} 条。检查范围为手机仍保留的采集记录；不可见可能是缺失、删除或无权限，不会自动恢复。来源快照由全量补传时核验。": "Проверка завершена: {0} видны на узле, {1} не видны. Охватывает записи захвата, ещё хранящиеся на телефоне. «Не видны» может означать отсутствие, удаление или отсутствие прав; ничего не восстанавливается автоматически. Полная повторная отправка проверяет снимки источников.",
  "检查失败：连接授权失效，请重新连接同一节点后重试": "Проверка не удалась: авторизация истекла. Переподключите тот же узел и повторите.",
  "中央节点尚不支持两端检查，请升级中央端代码；未修改本机状态": "Узел не поддерживает двусторонние проверки. Обновите его; локальное состояние не изменено.",
  "检查响应未确认": "Ответ проверки не подтверждён",
  "检查响应缺失": "Ответ проверки отсутствует",
  "已检查 {0} 条 · 中央可见 {1} · 不可见 {2}": "Проверено записей: {0} · Видны: {1} · Не видны: {2}",
  "操作未完成，已完成的步骤保留；请检查网络或存储。本次手动操作可再次点击继续，未删除任何副本。": "Операция не завершена; выполненные шаги сохранены. Проверьте сеть или хранилище и нажмите снова, чтобы продолжить. Копии не удалены.",
  "操作已请求；重复点击会合并，等待网络条件或当前操作完成": "Операция запрошена. Повторные нажатия объединяются; ожидание сетевых условий или завершения текущей работы.",
  "图片保存位置": "Расположение хранилища изображений",
  "本机保存待同步、待 OCR 与保留期内的记录和图片。上传后仍可回看，到期才清理。": "Локально хранит ожидающие синхронизации/OCR записи и изображения в пределах срока хранения. Загруженные записи доступны для просмотра до истечения срока.",
  "选择内部应用空间，或系统提供的本机／存储卡应用空间。迁移会自动暂停处理、复制并验证已有记录，然后继续原来的采集与同步。草稿、设置及来源缓存保留在内部空间。": "Выберите внутреннее хранилище приложения или предоставленное системой локальное хранилище/хранилище на SD-карте. Миграция приостанавливает обработку, копирует и проверяет записи, затем возобновляет прежний сбор и синхронизацию. Черновики, настройки и кэш источников остаются во внутреннем хранилище.",
  "默认明文保存：记录和索引为 JSON，图片保留原始格式。开发者选项可开启本地内容加密，也可批量解密旧文件。这些是本应用专用目录，不是共享相册；卸载应用会删除本机文件。移除存储卡后会停止使用该位置并提示，不会切到空目录；重新连接后可恢复。": "По умолчанию хранится в открытом виде: записи и индексы JSON, изображения в исходных форматах. В параметрах разработчика можно включить шифрование или расшифровать старые файлы. Это частные каталоги приложения, а не общий альбом; удаление приложения удаляет локальные файлы. Извлечение карты прекращает доступ с уведомлением, без переключения на пустой каталог. Переподключите для восстановления.",
  "正在读取存储位置…": "Загрузка расположений хранилища…",
  "当前保存位置\n{0}": "Текущее расположение\n{0}",
  "位置不可用：{0}\n已保留原位置，请重新连接原介质后重试。": "Расположение недоступно: {0}\nИсходное расположение сохранено. Переподключите исходный носитель и повторите.",
  "（当前）": "(текущее)",
  "{0}{1}\n可用 {2}\n{3}": "{0}{1}\nДоступно {2}\n{3}",
  "无法读取系统存储位置：{0}": "Не удалось прочитать системные расположения хранилища: {0}",
