  "迁移本机保存位置": "Перенести локальное хранилище",
  "迁移到{0}：\n{1}\n\n已有图片、待 OCR 结果和队列记录会一起迁移。验证成功后切换位置并清理旧副本。中央归档位置保持不变。": "Перенести в {0}:\n{1}\n\nИзображения, ожидающие результаты OCR и записи очереди переносятся вместе. После проверки расположение переключается, а старая копия очищается. Расположение центрального архива не меняется.",
  "迁移并应用": "Перенести и применить",
