  "屏幕采集权限说明": "О разрешении захвата экрана",
  "\n\n继续后请在系统设置中选择 Mote 屏幕采集。启用服务本身不会开始截图，仍需回到此处点击开始。": "\n\nПерейдите в системные настройки и выберите «Захват экрана Mote». Включение службы не запускает снимки экрана; вернитесь сюда и нажмите «Начать».",
