  "HyperOS 通知使用权：请按需打开实时、对话、通知、静音类别。旧版曾禁用这些类别；更新后若仍是灰色，可关闭再重新授予通知使用权。类别和应用级开关会影响可接收的事件。": "Для доступа к уведомлениям HyperOS включите категории «в реальном времени», «диалоги», «уведомления» и «беззвучные» по необходимости. Старые версии их отключали. Если после обновления они всё ещё серые, отзовите и снова предоставьте доступ. Категории и переключатели приложений влияют на получаемые события.",
  "通知权限": "Разрешение на уведомления",
