  "HyperOS 后台设置帮助": "Справка по фоновым настройкам HyperOS",
  "小米 / HyperOS：在系统应用设置中允许 Mote 自启动，将省电策略设为无限制，并允许通知；可在最近任务中锁定应用。菜单随系统版本变化。若侧载 APK 的无障碍开关受限，请在应用详情的菜单中检查“允许受限制的设置”。这些设置不能保证系统永不终止采集。": "Xiaomi / HyperOS: разрешите автозапуск, неограниченное использование батареи и уведомления. Приложение можно закрепить в недавних задачах. Меню различаются в зависимости от версии ОС. Если переключатель специальных возможностей для установленного из APK приложения ограничен, проверьте «Разрешить ограниченные настройки» в сведениях о приложении. Эти настройки не гарантируют непрерывный сбор.",
