  "{0}\n\n本机已有尚未绑定的截图、笔记或来源资料。确认后会绑定到这个档案地址，并按你的同步策略发送。请核对这是你自己的节点。": "{0}\n\nНа этом устройстве есть непривязанные снимки экрана, заметки или материалы источников. Подтверждение привяжет их к этому адресу архива и отправит согласно политике синхронизации. Убедитесь, что это ваш узел.",
