  "媒体播放状态授权": "Авторизация воспроизведения мультимедиа",
  "Android 通过通知使用权开放通知与媒体会话。开启通知采集后，Mote 会保存应用公开的标题、正文、持续状态以及更新和移除事件，并按同步策略上传。设备事件单独记录亮屏、熄屏和锁定状态。各来源需单独开启并点击开始；应用的“不记录”和“仅活动”规则仍适用。系统可能隐藏敏感通知；Mote 不回复通知、不控制播放。": "Android предоставляет доступ к уведомлениям и медиасеансам через доступ к уведомлениям. При включённом сборе уведомлений Mote сохраняет публичные заголовки, текст, постоянное состояние, обновления и удаления, затем загружает по политике. События устройства отдельно записывают состояния экрана и блокировки. Включите каждый источник и нажмите «Начать». Правила приложений «исключить» и «только активность» по-прежнему действуют. Система может скрывать конфиденциальные уведомления; Mote никогда не отвечает на них и не управляет воспроизведением.",
  "此系统入口不同，请在应用详情或系统搜索中查找": "В этой системе другой вход. Поищите в сведениях о приложении или в системном поиске.",
