  "固定遮罩示意图。在图上拖动添加矩形，点按矩形选中。也可用下方按钮添加和调整。": "Схема фиксированной маски. Перетаскивайте для добавления прямоугольников; нажмите один для выбора. Кнопки ниже добавляют и настраивают области.",
  "这些统计始终在本机保存，与开发者诊断开关独立。记录固定结果与数字，不记录画面、文字、应用名、邀请或令牌。": "Эта локальная статистика не зависит от переключателя диагностики. Она содержит фиксированные результаты и числа, но не изображения, текст, имена приложений, приглашения или токены.",
  "正在读取本机统计…": "Загрузка локальной статистики…",
