  "媒体已保存 {0} · 已确认 {1} · 失败 {2}\n": "Медиа сохранено: {0} · Подтверждено: {1} · Не удалось: {2}\n",
  "应用活动已保存 {0} · 已确认 {1} · 失败 {2}（无内容）\n": "Активности приложений сохранено: {0} · Подтверждено: {1} · Не удалось: {2} (без содержимого)\n",
  "已丢弃画面 {0} · 截图/处理失败 {1}\n": "Отброшено кадров: {0} · Сбоев захвата/обработки: {1}\n",
  "截图已确认上传 {0} · 随手记已确认上传 {1}\n": "Снимков подтверждено: {0} · Заметок подтверждено: {1}\n",
  "上传待重试结果 {0} · 来源版本已确认 {1} / 失败 {2}\n设备心跳失败 {3}\n": "Результатов повторных загрузок: {0} · Версий источников подтверждено: {1} / Не удалось: {2}\nСбоев heartbeat устройства: {3}\n",
  "已确认上传 JSON 字节 {0}（不含 TLS/HTTP 开销）\n": "Подтверждено байт JSON загрузки: {0} (без накладных расходов TLS/HTTP)\n",
  "\n记录明细抽样\n采集区保留：{0} 条，截图 {1} / 活动 {2} / 媒体 {3} / 系统事件 {4} / 笔记 {5} / 无法读取 {6} / 未检查 {7}（分类最多读取100条）\n": "\nВыборка записей\nСохранено захватов: {0}; снимки {1} / Активность {2} / Медиа {3} / Системные события {4} / Заметки {5} / Нечитаемые {6} / Непроверенные {7} (классификация читает не более 100 записей)\n",
  "\n资料在哪里\n队列存储：{0} / 上限 {1} MiB\n{2}\n": "\nГде хранятся данные\nХранилище очереди: {0} / Лимит {1} МиБ\n{2}\n",
  "待 OCR 文字预留：{0}（计入存储上限，完成识别后按实际大小计）\n": "Зарезервировано для текста OCR: {0} (учитывается в лимите; после распознавания — фактический размер)\n",
  "来源待确认版本：{0} · 本机来源缓存 {1}\n{2}\n": "Версий источников ожидает подтверждения: {0} · Локальный кэш источников: {1}\n{2}\n",
  "模型及下载断点：{0}\n{1}\n": "Модели и частичные загрузки: {0}\n{1}\n",
  "临时缓存：{0}\n{1}\n": "Временный кэш: {0}\n{1}\n",
  "应用私有文件合计：{0}\n设备此分区可用：{1}\n": "Всего приватных файлов приложения: {0}\nСвободно в разделе: {1}\n",
  "目录大小为最近测量值，最多缓存 30 秒；可点击上方刷新重新测量。\n": "Размеры каталогов — недавние измерения, кэшируются до 30 секунд. Обновите выше для повторного измерения.\n",
  "\n生效设置\n实际配置：每 {0} 秒，JPEG {1}，最长边 {2}px\n": "\nДействующие настройки\nФактическая конфигурация: каждые {0} сек., JPEG {1}, макс. сторона {2}px\n",
  "开启": "Вкл.",
  "仅非计费 Wi-Fi：{0} · 仅充电采集：{1} · 低于 {2}% 暂停（0 关闭）\n": "Только безлимитный Wi-Fi: {0} · Сбор только при зарядке: {1} · Пауза ниже {2}% (0 отключает)\n",
  "开启，充电后补做历史图片": "Вкл.; исторические изображения обрабатываются во время зарядки",
  "仅充电 OCR：{0}\n": "OCR только при зарядке: {0}\n",
  "本机过滤：{0} · {1} 线程 · {2}ms 超时\n": "Локальная фильтрация: {0} · потоков: {1} · тайм-аут {2} мс\n",
  "上传新记录的实际状态": "Наблюдаемое состояние загрузки с новыми записями",
  "新记录不附带": "Не включать в новые записи",
  "设备元数据：{0} · 应用规则 {1} 项\n": "Метаданные устройства: {0} · правил приложений: {1}\n",
  "\n统计口径与限制\n已保存表示本机入队成功；已上传表示节点已确认收到。待 OCR 的图片在确认上传后仍会保留，补做结果也同步成功后才清理。被过滤的画面不会入队。暂停是原因变更次数，不等于丢弃截图次数；请求可能因系统/进程中断没有后续结果。统计与队列分开持久化，进程在两次写入之间终止时累计数可能少记；当前队列数量包含待识别和同步失败保留的图片。\n": "\nОпределения и ограничения\n«Сохранено» означает постановку в локальную очередь; «загружено» — подтверждение узлом. Изображения, ожидающие OCR, остаются после загрузки, пока результаты OCR тоже не синхронизируются. Отфильтрованные кадры в очередь не ставятся. Счётчики пауз отражают смену причин, а не число отброшенных снимков; прерванные запросы могут не иметь результата. Статистика и очереди сохраняются раздельно, поэтому завершение процесса между записями может занизить итоги. Числа очереди включают изображения, ожидающие OCR и сохранённые после сбоев синхронизации.\n",
  "文件字节合计不是 Android 系统的安装占用；不含 APK、系统配额或其他分区。目录仅可由本应用读取，不是共享相册。": "Сумма байтов файлов — не объём установки Android; APK, системные квоты и другие разделы не учитываются. Каталоги приватны для этого приложения, это не общие альбомы.",
  "统计或队列暂不可读取，不能按零展示；原始文件保留，请查看支持诊断。": "Статистика или очередь временно нечитаемы; ноль показать нельзя. Оригиналы сохранены. См. диагностику поддержки.",
  "本机保留记录（第 {0} 页，每页 10 条；图片与文字请打开采集记录）": "Локально сохранённые записи (страница {0}, по 10; изображения и текст — в записях захвата)",
  "中央不可更新": "Центральная запись недоступна для записи",
  "已同步保留": "Синхронизировано и сохранено",
  "媒体状态": "Состояние медиа",
  "记录 ID：{0}\n创建：{1}\n条目字节：{2}\n本机仍保留此记录；下方历史同一 ID 可关联上传失败和确认。图片与文字可从采集记录查看。": "ID записи: {0}\nСоздана: {1}\nБайт записи: {2}\nЭта запись остаётся локальной. Сопоставьте её ID с историей сбоев и подтверждений ниже. Изображения и текст — в записях захвата.",
