  "{0}\n{1}\n记录 ID：{2}\n原因：{3}\n记录字节：{4}\nHTTP：{5}\n耗时：{6}\n不保存内容预览；待上传记录只有匹配节点 ACK 后删除。": "{0}\n{1}\nID записи: {2}\nПричина: {3}\nБайт записи: {4}\nHTTP: {5}\nДлительность: {6}\nПредпросмотр содержимого не сохраняется. Ожидающие записи удаляются только после соответствующего ACK узла.",
