  "来源限制与同步说明": "Ограничения источников и синхронизация",
  "来源说明": "Об источниках",
  "默认扩展名 md/txt/json/csv/ics，正文只接受 UTF-8；单文件 100 KiB、100000 字符，单次最多 200 项和 4 MiB，来源缓存最多 64 MiB（也遵守采集与存储中的队列上限）。超限或扫描不完整会提示，绝不把漏扫项当作删除。\n系统后台任务约每 15 分钟检查一次来源各自的间隔；省电或强行停止可能推迟，重新打开应用可恢复。原件归档每文件最多 512 MiB，Mote 文件暂存最多 1 GiB；自动等待稳定后上传，断网续传。引用模式不读取原件，不受原件大小限制。": "Расширения по умолчанию: md/txt/json/csv/ics, только текст UTF-8. Лимиты: 100 КиБ/100000 символов на файл; 200 элементов/4 МиБ за сканирование; кэш источника 64 МиБ, также ограничен ёмкостью очереди. О лимитах и неполных сканированиях сообщается; пропущенные элементы никогда не считаются удалёнными.\nФоновые задачи проверяют интервалы источников примерно каждые 15 минут. Энергосбережение или принудительная остановка могут их задержать; повторное открытие восстанавливает работу. Архив оригиналов допускает 512 МиБ на файл и 1 ГиБ промежуточного хранения Mote, ждёт стабильных файлов и возобновляет загрузку после обрыва сети. Режим ссылок не читает оригинал и не имеет ограничения по его размеру.",
