  "本地删除不影响中央原件；上传后仅清理 Mote 暂存，保留手机原文件。仅同步新增以首次完整清单为基线，重启不会重置。": "Локальное удаление не влияет на центральные оригиналы. Очистка после загрузки удаляет только промежуточное хранилище Mote, сохраняя оригиналы на телефоне. Синхронизация только новых элементов использует первый полный список как базу; перезапуск её не сбрасывает.",
  "扫描间隔 / 分钟（15–1440，系统可能推迟）": "Интервал сканирования / минуты (15–1440; система может задержать)",
