  "更改选择、过滤或保留方式会清除这个来源的本机旧待发缓存，按新设置重新扫描；不会自动删除中央历史。停用仅暂停本机检查与同步，中央的启用状态与历史保持不变。移除只影响本机连接。": "Изменение выбора, фильтров или режима хранения очищает старый локальный кэш ожидания этого источника и запускает повторное сканирование с новыми настройками. Центральная история не удаляется. Отключение приостанавливает только локальные проверки и синхронизацию. Удаление влияет только на локальное подключение.",
