  "通知权限已关闭，为保持采集可见已停止，请授权通知后重新开始": "Захват остановлен: разрешение на уведомления отключено. Предоставьте разрешение и запустите снова, чтобы захват оставался видимым.",
  "此系统需投屏模式采集内容；仅应用活动无需截图API": "Для захвата содержимого в этой системе требуется демонстрация экрана; одна активность приложений не требует API скриншотов.",
  "系统未提供截图（代码 {0}），可能是安全窗口或权限变化；未保存内容": "Система не предоставила скриншот (код {0}); возможно, из-за защищённого окна или изменения разрешений. Содержимое не сохранено.",
