  "仍有 {0} 条待发及 {1} 项来源设置待确认；暂停或权限不可用的来源需恢复后同步": "По-прежнему ожидают записей: {0} и настроек источников: {1}; возобновите приостановленные источники или восстановите разрешения для синхронизации.",
  "当前待发已确认 · {0} 张图片等待本机 OCR，完成后继续同步": "Ожидающие записи подтверждены · изображений ждут локального OCR: {0}; синхронизация продолжится после обработки.",
  "当前待发记录已获中央确认；这不表示两端保留数量相同": "Центральный узел подтвердил все ожидающие записи; это не означает, что стороны хранят одинаковое количество.",
