  "本地服务必须使用回环地址，远程服务必须使用 HTTPS，地址不可包含凭据或查询参数": "Локальные сервисы требуют loopback-адреса; удалённые сервисы требуют HTTPS. Учётные данные и параметры запроса в URL не допускаются.",
  "语言模型服务需要填写模型名称": "Укажите имя модели для сервисов языковых моделей.",
  "服务和方案 ID 必须各自唯一": "ID сервисов и профилей должны быть уникальными.",
  "同一来源和类型只能配置一条规则": "Для каждой пары источник-тип допускается только одно правило.",
  "需要配置其他类型的默认规则": "Настройте правило по умолчанию для остальных типов.",
  "规则引用了不存在的方案": "Правило ссылается на несуществующий профиль.",
