  "记录通知中心可见内容": "Записывать видимое содержимое Центра уведомлений",
  "需要 macOS 辅助功能授权。仅记录系统当前公开的通知视图，无法读取未展示或已消失的通知。启用应用排除或仅活动规则时暂停此功能。": "Требуется доступ к универсальному доступу (Accessibility) macOS. Записываются только видимые сейчас уведомления; скрытые или уже закрытые уведомления недоступны. Правила исключения приложений или «только активность» приостанавливают эту функцию.",
  "网页版本": "Версия веб-приложения",
  "网页与服务版本不一致，请重新构建网页并刷新页面。": "Версии веб-приложения и сервера различаются. Пересоберите веб-приложение и обновите страницу.",
  "统计中心": "Статистика",
  "当前磁盘占用，按文件类型和最后修改日期（UTC）汇总。共享文件只计一次；日期分布不是每日新增量。": "Текущее использование диска по типам файлов и дате последнего изменения (UTC). Общие файлы учитываются один раз. Распределение по датам — не ежедневный прирост.",
