  "导出所选时段内全部已保留日志；日志轮转前已清理的部分无法恢复，导出包会注明覆盖范围。": "Экспортировать все сохранённые журналы за выбранный период. Удалённые при ротации журналы восстановить нельзя; экспорт указывает свой охват.",
  "内容索引，原件留本机": "Индекс содержимого; оригиналы остаются на устройстве",
  "仅文件目录": "Только каталог файлов",
