  "允许中央按需读取此目录的正文片段（设备需在线）": "Разрешить центральному узлу читать фрагменты текста по запросу (устройство должно быть в сети)",
  "文件来源每份 ≤16 MiB；支持文本、PDF、Word 和音频。跳过隐藏项和符号链接。": "Файлы до 16 МиБ: текст, PDF, Word и аудио. Скрытые файлы и символические ссылки пропускаются.",
  "原件归档不能应用文字遮盖，请选择内容索引。": "При архивировании оригиналов нельзя скрывать текст. Выберите индексирование содержимого, чтобы использовать маскировку.",
  "索引待处理，原件留本机": "Индекс ожидает обработки; оригинал на устройстве",
