  "需要设备在线读取更多正文": "Устройство должно быть в сети для чтения дополнительного текста",
  "字符": "символов",
  "文件索引或目录已同步；原件留本机": "Индекс файлов или каталог синхронизированы; оригиналы остаются на устройстве",
  "按日期和文件类型查看空间占用": "Использование хранилища по дате и типу файлов",
  "时间范围": "Временной диапазон",
  "相同状态合并为 {0} 次观察，最近一次：{1}。统计逐次使用实测时长，观察间隙不计为连续使用。": "Одинаковое состояние в {0} наблюдений; последнее: {1}. Статистика использует каждый измеренный интервал и не считает паузы между наблюдениями непрерывным использованием.",
  "合并 {0} 次状态观察": "{0} наблюдений состояния объединено",
