  "请刷新检查结果，避免重复发送。": "Обновите, чтобы проверить результат перед повторной отправкой.",
  "删除已下载包": "Удалить загруженные пакеты",
  "正在删除更新包…": "Удаление пакетов обновлений…",
  "删除下载的 APK 和未完成下载，保留应用设置和记录；需要时可以重新下载。": "Удалить загруженные APK и незавершённые загрузки. Настройки приложения и записи сохраняются; пакеты можно загрузить снова.",
  "中央所有者令牌（设备凭据没有问答权限）": "Токен владельца центрального узла (учётные данные устройства не могут использовать «Спросить»)",
