  "记录固定事件、状态与数值指标。silent 日志级别会同时停止记录。": "Записывать фиксированные события, состояния и метрики. Уровень журнала silent также отключает запись.",
  "详细 Agent 执行跟踪": "Подробные трассы выполнения агента",
  "显式记录 Agent 的请求上下文、组装后的 prompt、模型输出、工具参数与结果、校验和阶段状态到 central 日志。包含个人内容，只建议开发环境开启；开发环境默认开启。": "Записывать контекст запросов агента, собранные промпты, выводы модели, аргументы и результаты инструментов, проверку и этапы в центральные журналы. Содержит личное содержимое; рекомендуется только для разработки, где включено по умолчанию.",
  "回看最近记录，确认下一步行动": "Просмотрите недавние записи и подтвердите следующие действия",
  "最近记录": "Недавние записи",
