  "已注册的处理器及其版本。扩展由节点管理，不提供在线安装。": "Зарегистрированные обработчики и их версии. Расширения управляются узлом; онлайн-установка недоступна.",
  "查看处理步骤、依赖与等待原因。重试保留其他已完成步骤。": "Проверьте шаги, зависимости и причины ожидания. Повтор сохраняет другие завершённые шаги.",
  "重试此步骤": "Повторить этот шаг",
  "中央服务从源码部署，升级前先备份。当前不提供应用内自动更新。": "Центральный сервис развёртывается из исходного кода; перед обновлением сделайте резервную копию. Автоматическое обновление в приложении пока недоступно.",
