  "处理服务拒绝了凭据，请检查服务权限与密钥。": "Сервис обработки отклонил учётные данные. Проверьте его разрешения и API-ключ.",
  "处理服务地址不可用，请检查端点配置。": "Конечная точка обработки недоступна. Проверьте её конфигурацию.",
