  "无法连接处理服务，请检查网络与服务地址。": "Не удаётся подключиться к сервису обработки. Проверьте сеть и адрес конечной точки.",
  "处理服务拒绝了内容大小，请缩小本次处理范围。": "Сервис обработки отклонил размер содержимого. Уменьшите объём обработки.",
