  "处理服务拒绝了请求参数，请检查处理配置。": "Сервис обработки отклонил параметры запроса. Проверьте конфигурацию обработки.",
  "审核记录": "История проверок",
  "复用了相同候选与证据版本的独立审核结果，并重新校验了引用和范围。": "Использован повторно результат независимой проверки идентичных версий кандидата и доказательств с повторной проверкой цитат и охвата.",
  "候选已经过独立模型审核和引用校验；用户确认单独记录。": "Кандидат прошёл независимую проверку модели и проверку цитат. Подтверждение пользователя записывается отдельно.",
  "审核编号": "ID проверки",
