  "确认后修改或取消原设备上的这一条日程；不会新建另一条日程。": "Подтверждение изменит или отменит это событие на исходном устройстве без создания нового события.",
  "保存后会交给该设备写入，备注中附加 #Mote 标记。不会邀请参与人。": "После сохранения это устройство запишет событие с пометкой #Mote. Участники приглашены не будут.",
