  "部分资料仍未完成处理或仅保留来源引用，内容覆盖不完整。": "Часть материалов ещё обрабатывается или содержит только ссылки на источники. Покрытие содержимого неполное.",
  "此报告是同一范围的新版本，旧报告保留各自的资料快照。": "Это новая версия отчёта для того же охвата. Прежние отчёты сохраняют свои снимки доказательств.",
