  "存在矛盾的记忆": "Противоречащее воспоминание",
  "确认后才应用此关系，旧内容仍保留。": "Эта связь применяется только после подтверждения. Прежнее содержимое сохраняется.",
  "纠正并确认": "Исправить и подтвердить",
  "填写你确认的内容。它将作为你的原始说明保存，生成新版本；旧记忆及其证据仍可查看，适用项目保持不变。": "Введите содержимое, которое вы подтверждаете. Оно сохранится как ваше исходное описание и новая версия. Прежняя память и доказательства остаются доступными, охват проекта не меняется.",
  "你确认的内容": "Подтверждаемое вами содержимое",
