  "日程分析未完成，请查看批次状态后重试。": "Анализ календаря не завершён. Проверьте статус партий перед повтором.",
  "模型返回的日程建议未通过校验，请重试分析。": "Предложения календаря от модели не прошли проверку. Запустите анализ снова.",
  "上传已暂停；已选择的文件仍保留，可继续上传。": "Загрузка приостановлена. Выбранные файлы сохранены; загрузку можно продолжить.",
  "暂停上传": "Приостановить загрузку",
  "普通文本会自动保存为记录；原件始终保留。": "Обычный текст автоматически сохраняется как записи. Оригиналы всегда сохраняются.",
  "正在创建导入…": "Создание импорта…",
