  "校验回答": "Проверка ответа",
  "校验完成": "Проверка завершена",
  "换个视角，看看 Agent 能看到什么": "Посмотрите, что видит ваш агент",
  "打开它的目录，查看首次上下文和实际读取。": "Откройте его каталог, начальный контекст и фактические чтения.",
  "运行完成": "Запуск завершён",
  "运行失败": "Запуск не удался",
  "本次返回内容": "Содержимое, возвращённое в этом запуске",
  "已保留 {0} 个媒体原件，确认接入后按文件处理设置提取内容；当前尚未转写。": "Сохранено {0} медиа-оригиналов. После приёма содержимое будет извлечено по настройкам обработки файлов; транскрипция ещё не выполнялась.",
  "媒体已接入": "Медиа принято",
  "等待内容提取": "Ожидание извлечения содержимого",
