  "未启用自动记忆": "Автоматическая память отключена",
  "文件管线": "Конвейер файлов",
  " · {0} 个进入文件处理": " · {0} в очереди на обработку файлов",
  "媒体原件按文件处理设置提取内容；记忆整理等待所需内容就绪。": "Медиа-оригиналы обрабатываются по настройкам обработки файлов. Память ждёт готовности нужного содержимого.",
  "{0} 条文本记录，{1} 个媒体原件将进入文件处理": "{0} текстовых записей и {1} медиа-оригиналов будут приняты в обработку файлов",
  "媒体处理进度": "Прогресс обработки медиа",
  "已接入不等于已可搜索。内容提取、搜索和记忆整理分别显示状态。": "Приём не означает, что содержимое доступно для поиска. Извлечение, доступность поиска и память имеют отдельные статусы.",
  "已有可搜索片段": "Есть сегменты, доступные для поиска",
  "尚无可搜索片段": "Пока нет сегментов для поиска",
  "等待内容就绪": "Ожидание содержимого",
  "重试处理": "Повторить обработку",
  "飞书录音 / 妙记": "Записи Feishu / Minutes",
  "钉钉录音 / 闪记": "Записи DingTalk / Flash Notes",
  "发现记录": "Обнаружение записей",
  "读取信息": "Чтение метаданных",
  "归档转写": "Архивация расшифровок",
  "备份音频": "Резервное копирование аудио",
  "中央节点需要安装 Lark CLI 并完成飞书账号授权。": "Установите Lark CLI и авторизуйте Feishu на центральном узле.",
  "请先在中央节点完成飞书账号授权，再连接录音。": "Авторизуйте Feishu на центральном узле, прежде чем подключать записи.",
  "中央节点需要安装 DWS CLI 并完成钉钉账号授权。": "Установите DWS CLI и авторизуйте DingTalk на центральном узле.",
  "请先在中央节点完成钉钉账号授权，再连接录音。": "Авторизуйте DingTalk на центральном узле, прежде чем подключать записи.",
  "账号已变化，请重新连接并确认同步范围。": "Аккаунт изменился. Переподключитесь и подтвердите диапазон синхронизации.",
  "读取权限不足或授权已失效，请重新连接后重试。": "Недостаточно разрешений на чтение или авторизация истекла. Переподключитесь и повторите.",
  "厂商转写尚未就绪，将自动重试。": "Расшифровка поставщика ещё не готова. Mote повторит автоматически.",
  "同步未完成，请检查节点网络与厂商读取权限后重试。": "Синхронизация не завершена. Проверьте связность узла и разрешения на чтение у поставщика, затем повторите.",
  "连接中央节点已经授权的厂商账号，然后选择首次导入时间。": "Подключите аккаунт поставщика, авторизованный на центральном узле, затем выберите диапазон первого импорта.",
  "连接已授权账号": "Подключить авторизованный аккаунт",
  "首次授权帮助": "Справка по первой авторизации",
  "在中央节点安装并登录官方 Lark CLI。需要妙记搜索、基础信息、产物读取和媒体导出权限。": "Установите официальный Lark CLI на центральном узле и войдите в него. Требуются разрешения на поиск Minutes, метаданные, артефакты и экспорт медиа.",
  "在中央节点安装并登录官方 DWS CLI；所在组织需开启 CLI 接入。钉钉适配器尚未完成真实账号验证。": "Установите официальный DWS CLI на центральном узле и войдите в него. Ваша организация должна включить доступ через CLI. Адаптер DingTalk ещё не проверен на реальном аккаунте.",
  "首次历史导入起点": "Начало первого импорта истории",
  "导入终点（留空持续同步）": "Конец импорта (оставьте пустым для постоянной синхронизации)",
  "启用录音同步": "Включить синхронизацию записей",
  "保存并开始同步": "Сохранить и начать синхронизацию",
  "重试失败步骤": "Повторить неудавшиеся шаги",
  "已归档转写 {0} 条，音频 {1} 条；等待 {2} 步，需处理 {3} 步。": "Заархивировано {0} расшифровок и {1} аудиофайлов; {2} шагов в ожидании, {3} требуют внимания.",
  "同步步骤与状态": "Шаги и статус синхронизации",
  "尝试 {0} 次": "{0} попыток",
  "录音归档": "Архив записей",
  "照常使用录音笔。厂商完成上传和转写后，Mote 自动归档并生成可追溯的 Memory。": "Пользуйтесь диктофоном как обычно. После того как поставщик загрузит и расшифрует запись, Mote архивирует её и создаёт отслеживаемую память.",
  "默认用转写生成洞察，原始音频在后台备份。厂商端删除后，Mote 归档继续保留。停止同步或断开连接会保留历史资料。": "По умолчанию расшифровки используются для инсайтов, а исходное аудио резервно копируется в фоне. Mote сохраняет свои архивы после удаления у поставщика, остановки синхронизации или отключения аккаунта.",
