  "稍后再说": "Ответить позже",
  "此补充对话暂不可用，请刷新或查看相关资料。": "Это уточнение временно недоступно. Обновите или просмотрите связанный материал.",
  "我有新信息了": "У меня есть новая информация",
  "补充问题记录": "История уточнений",
  "归属仍然未知，本次评估已结束；原始资料继续保留。": "Принадлежность остаётся неизвестной. Эта оценка завершена; исходный материал сохранён.",
  "回答已保存到这份资料。相关范围将重新提取并独立复核。": "Ваш ответ сохранён для этого материала. Затронутые диапазоны будут извлечены и независимо проверены заново.",
  "首页": "Главная",
  "添加": "Добавить",
