  "文件选择已失效，请重新选择": "Выбор файла истёк. Выберите его снова.",
  "单次导入已保存在本机；不会检查后续修改": "Одноразовый импорт сохранён локально. Последующие изменения проверяться не будут.",
  "全部发送已暂停；本机记录与来源检查继续": "Вся отправка приостановлена. Локальная запись и проверка источников продолжаются.",
