  "本机保存、中央接收与整理完成分别显示；接收确认不代表已经可以搜索。": "Локальное сохранение, центральное получение и обработка отображаются отдельно. Получение не означает, что содержимое уже доступно для поиска.",
  "暂停全部发送": "Приостановить всю отправку",
