  "尚未添加文件夹。添加后可在这里查看范围和状态。": "Папки ещё не добавлены. Их область и состояние появятся здесь.",
  "还没有内容。选一个动作，留下第一份资料。": "Содержимого пока нет. Выберите действие, чтобы сохранить первый элемент.",
  "这里还没有内容。点击添加，选择文件、屏幕或随手记。": "Содержимого пока нет. Нажмите «Добавить», чтобы выбрать файлы, экраны или быструю заметку.",
  "保存范围后开始，系统权限按需申请。拒绝授权不影响文件和随手记。": "Сохраните область, чтобы начать. Разрешения запрашиваются по мере необходимости; отказ не влияет на файлы и быстрые заметки.",
