  "正在保存发送状态…": "Сохранение состояния отправки…",
  "中央问答暂不可用。连接中央后，可以根据已整理的内容提问；文件和随手记仍可在本机保存。": "Вопросы к центральному архиву недоступны. Подключитесь, чтобы спрашивать об обработанном содержимом. Файлы и быстрые заметки по-прежнему можно сохранять локально.",
  "查看自动同步的范围，逐个暂停或修复来源。": "Просмотрите область непрерывной синхронизации. Приостановите или восстановите каждый источник.",
