  "只读取你明确选择的范围。暂停屏幕记录、暂停来源和暂停全部发送分别生效。": "Читается только выбранная вами область. Приостановка записи экрана, источника или всей отправки действует раздельно.",
  "先确认应用与遮挡范围，再由你开始记录。屏幕权限不影响文件和随手记。": "Подтвердите приложения и маски, затем сами начните запись. Разрешения на экран не влияют на файлы и заметки.",
  "哪些日常可以留下，由你决定。": "Вы решаете, что можно сохранять.",
  "选择应用、遮挡区域和记录方式，开始前会再次确认保存范围。": "Выберите приложения, маски и режим записи. Проверьте сохранённую область перед началом записи.",
