  "文件、屏幕和想法，在同一处阅读。点开内容即可核对出处和整理状态。": "Читайте файлы, экраны и идеи в одном месте. Откройте элемент, чтобы проверить источник и состояние обработки.",
  "查看内容": "Показать содержимое",
  "本机与已发送": "Локальное и отправленное содержимое",
  "加载更多": "Загрузить ещё",
  "按日期浏览屏幕与页面记录": "Просматривать записи экрана и страниц по датам",
  "管理你选择的文件夹、文件、日历和编码对话。每个来源都可单独暂停。": "Управляйте выбранными папками, файлами, календарями и диалогами программирования. Приостанавливайте каждый источник независимо.",
  "确认添加内容": "Подтвердить добавление содержимого",
  "完整文件会发送到所示中央节点进行处理；提取正文不代表只上传摘要。未连接时先保存本机任务，首次连接须确认发送范围。": "Полный файл отправляется на отображаемый центральный узел для обработки. Извлечение текста не означает загрузку только сводки. При отключении сохраните задачу локально; подтвердите область отправки при первом подключении.",
