  "这是生成的格式示意，不读取你的屏幕。仅应用活动不读取屏幕或正文；完整内容保存经过遮挡的截图或获准页面。": "Этот сгенерированный пример формата не читает ваш экран. «Активность приложения» не читает экраны и текст; «полное содержимое» сохраняет замаскированные снимки или авторизованные страницы.",
