  "读取兼容发布包，预览版本、能力与访问范围后安装。GitHub 数据连接器仍在资料来源中管理。": "Определите совместимый релиз и проверьте его версию, возможности и доступ перед установкой. Подключения данных GitHub остаются в разделе «Источники».",
