  "自动记忆": "Автоматическая память",
  "控制自动提取与整合；原件、已有记忆与只读查询保留。独立回顾按自己的设置运行。": "Управление автоматическим извлечением и интеграцией. Оригиналы, существующая память и запросы только для чтения остаются доступными. Личные обзоры следуют собственным настройкам.",
  "已选择暂停": "Запрошена пауза",
  "排队 {0} · 运行 {1} · 检查点 {2} · 结果待确认 {3}": "В очереди {0} · выполняется {1} · с контрольными точками {2} · не подтверждено {3}",
  "当前准入代次 {0} · 绑定代次 {1}": "Поколение допуска {0} · поколение привязки {1}",
  "暂停期间的新资料只归档。恢复只处理新资料，不会自动补跑暂停期间的历史。": "Новые данные во время паузы только архивируются. Возобновление обрабатывает только новые данные; история периода паузы не воспроизводится автоматически.",
  "已停止新增自动任务；已授权任务保留原范围与代次，完成后停用。": "Приём новых автоматических задач остановлен. Ранее авторизованные задачи сохраняют исходную область и поколение и завершаются перед отключением.",
  "外部结果尚未确认，停止请求不代表远端工作已结束。": "Внешние результаты не подтверждены. Запрос на остановку не доказывает завершение удалённой работы.",
  "立即停止": "Остановить немедленно",
  "查看任务详情": "Показать сведения о задаче",
  "完整引擎": "Полный движок",
  "模块组合": "Комбинация модулей",
  "当前": "Текущий",
  "准备与生效分开执行。只有范围、正文与索引核验通过后，才能切换写入与查询绑定。": "Подготовка и активация разделены. Привязки записи и запросов меняются только после проверки области, содержимого и индексов.",
  "预览更换": "Просмотреть замену",
  "高级：当前模块与绑定": "Дополнительно: текущие модули и привязки",
  "绑定版本": "Ревизия привязки",
  "绑定代次 {0}": "Поколение привязки {0}",
  "独立审查与授权由 Mote 保留。只展示实际注册与核验过的模块。": "Mote сохраняет независимую проверку и авторизацию. Показаны только зарегистрированные модули и их фактическое состояние проверки.",
  "方案准备": "Подготовка плана",
  "正文迁移与索引准备": "Миграция содержимого и подготовка индексов",
