  "资料库 → 记忆 → 历史 / 截至时间筛选 → 记忆详情": "Библиотека → Память → Фильтры истории / по состоянию на → Детали памяти",
  "资料库 → 记忆 → 提取记忆；原始或正式资料详情 → 记忆提取": "Библиотека → Память → Извлечь память; Детали исходного или официального материала → Извлечение памяти",
