  "资料库 → 文件与录音 → 文件详情；导入 → 媒体详情": "Библиотека → Файлы и записи → Детали файла; Импорт → Детали медиа",
  "资料库 → 应用活动": "Библиотека → Активность приложений",
  "资料库 → 原始采集记录": "Библиотека → Исходные записи захвата",
  "资料库 → 原始采集记录 → 记录 → 完整详情": "Библиотека → Исходные записи захвата → Запись → Полные детали",
  "资料库 → 原始采集记录 → 完整详情 → 删除这条记录": "Библиотека → Исходные записи захвата → Полные детали → Удалить эту запись",
  "资料库分类是内容视图；设备端负责采集，时间统计只基于实际观测。": "Категории библиотеки — это представления контента. Устройства собирают данные; статистика времени основана только на фактических наблюдениях.",
  "资料库分类是已有内容的视图；页面工具与分类视图使用不同入口。": "Категории библиотеки — представления существующего контента. Инструменты страницы и представления категорий используют разные точки входа.",
  "资料库分类是已有内容的视图；Coding 接收状态在处理任务内查看，已发布正文在全部资料阅读。": "Категории библиотеки — представления существующего контента. Статусы приёма Coding отображаются внутри задач обработки, а опубликованный текст читается в разделе «Все материалы».",
  "资料库工具 → 导入 → 本地上传队列": "Инструменты библиотеки → Импорт → Локальная очередь загрузки",
  "资料库工具 → 导入 → 导入详情": "Инструменты библиотеки → Импорт → Детали импорта",
  "资料库工具 → 导入 → 导入详情 → 删除这次导入": "Инструменты библиотеки → Импорт → Детали импорта → Удалить этот импорт",
  "资料库工具 → 导入 → 服务器目录": "Инструменты библиотеки → Импорт → Каталог сервера",
  "资料库工具 → 导入 → 解析方式 / 修改图片处理": "Инструменты библиотеки → Импорт → Метод разбора / Изменить обработку изображений",
  "资料库工具 → 洞察；问一问 → 查看洞察；今天 → 最近洞察": "Инструменты библиотеки → Инсайты; Спросить → Просмотр инсайтов; Сегодня → Последний инсайт",
  "资料库工具 → 随手记": "Инструменты библиотеки → Быстрые заметки",
