  "原任务入口当前不可用，请从主导航继续。": "Исходный пункт задачи сейчас недоступен. Продолжите через главную навигацию.",
  "这里仅核对首个关联执行记录；还有 {0} 个关联记录，可在技术详情继续查看。已有补充问题单独显示在下方。": "Здесь проверяется только первая связанная запись выполнения. Ещё связанных записей: {0} — их можно просмотреть в разделе «Технические детали». Существующие уточняющие вопросы показаны отдельно ниже.",
  "此资料库分类当前不可用。请从资料库分类中选择可用入口。": "Эта категория библиотеки сейчас недоступна. Выберите доступный пункт среди категорий библиотеки.",
  "厂商转写格式尚不支持。音频备份是独立步骤，请分别核对转写与音频的状态。": "Формат транскрипта поставщика пока не поддерживается. Резервное копирование аудио — отдельный шаг; проверяйте статус транскрипта и аудио по отдельности.",
  "同步未完成（原因代码：{0}）。请查看同步步骤，核对实际原因后再重试。": "Синхронизация не завершена (код причины: {0}). Проверьте шаги синхронизации, установите фактическую причину и повторите.",
  "核对原因后，可使用上方「重试失败步骤」。转写与音频状态分别核对。": "Проверив причину, можно воспользоваться пунктом «Повторить неудачные шаги» выше. Статус транскрипта и аудио проверяется отдельно.",
  "文件夹进度：中央已接收 {0}/{1} 个当前版本（{2}%）": "Прогресс папки: центральный узел получил текущих версий: {0}/{1} ({2} %)",
  "等待稳定 {0} · 排队 {1} · 正在保存 {2} · 正在上传 {3} · 失败重试 {4} · 需处理 {5}": "Ожидают стабильности: {0} · В очереди: {1} · Сохраняются: {2} · Загружаются: {3} · Ожидают повтора: {4} · Требуют внимания: {5}",
