  "三个采集项独立执行；全部取消即不采集。": "Три параметра захвата выполняются независимо; снимите все, чтобы прекратить захват этого приложения.",
  "应用列表读取失败，可重试；已有配置仍可编辑。": "Не удалось прочитать список приложений; можно повторить. Существующие настройки остаются доступными для редактирования.",
