  "按用途授权 · 规划中": "Авторизация по назначению · Запланировано",
  "按用途推荐权限和 Agent 专属连接向导尚未开放。当前只读 MCP 可检索已获准的归档资料；写入必须单独授权。": "Рекомендации разрешений по назначению и мастера подключения агентов пока недоступны. MCP только для чтения может искать разрешённые архивные материалы; запись требует отдельной авторизации.",
  "还没有设备连接。生成邀请即可添加。": "Подключённых устройств пока нет. Создайте приглашение, чтобы добавить.",
  "还没有 AI 连接。生成 MCP 配置即可添加。": "Подключений ИИ пока нет. Создайте конфигурацию MCP, чтобы добавить.",
  "这份洞察当前不可用，请从历史选择其他洞察。": "Этот инсайт сейчас недоступен. Выберите другой инсайт из истории.",
  "上传历史保存时长": "Срок хранения истории загрузок",
  "默认保存30天。到期只清理上传历史，不删除资料、待传原件或草稿。": "По умолчанию 30 дней. По истечении срока очищается только история загрузок — материалы, ожидающие оригиналы и черновики не удаляются.",
  "默认30天，仅清理历史，不删除资料": "По умолчанию 30 дней; очищается только история, материалы не удаляются",
  "保存未完成，请重试；资料和待传原件保留。": "Сохранение не завершилось. Повторите; материалы и ожидающие оригиналы сохранены.",
