  "历史版本不可用：本机原件已更新或清理，不能将当前内容作为这次上传的原文。": "Историческая версия недоступна: локальный оригинал изменился или был очищен. Текущее содержимое нельзя считать оригиналом этой загрузки.",
  "采集与随手记的上传批次；其他上传结果可在采集与存储详情查看。": "Пакеты загрузок захвата и быстрых заметок. Остальные результаты загрузок доступны в деталях захвата и хранения.",
  "上传历史": "История загрузок",
  "上传历史暂不可读取，请刷新重试。": "История загрузок сейчас недоступна. Обновите и повторите.",
  "上传结果详情": "Детали результата загрузки",
  "仅显示本机保留的最近上传结果；中央接收不代表已完成处理。": "Показаны последние результаты загрузок, сохранённые на этом устройстве. Получение центральным узлом не означает завершение обработки.",
  "删除中央保存的这份文件。不会删除设备上的原件，也不会改变来源同步策略。删除后无法恢复。": "Удалить этот файл, хранящийся на центральном узле. Оригиналы на устройствах и политика синхронизации источника не меняются. Действие необратимо.",
  "删除中央保存的这条记录。不会删除本机副本或来源原件，也不会改变来源同步策略。删除后无法恢复。": "Удалить эту запись, хранящуюся на центральном узле. Локальные копии, оригиналы источника и политика синхронизации источника не меняются. Действие необратимо.",
