  "安装未完成，请查看已登记的插件状态。": "Установка не завершилась. Проверьте зарегистрированное состояние плагина.",
  "请检查连接配置；仅使用已有模型与凭据引用，不填写密钥。": "Проверьте настройки подключения; используйте ссылки на существующие модели и учётные данные, а не секретные значения.",
  "正在核验能力…": "Проверка возможностей…",
  "能力已核验。启用与记忆方案仍需单独选择。": "Возможности проверены. Включение и выбор плана памяти — отдельные действия.",
  "连接配置已保存，尚未核验能力。": "Настройки подключения сохранены; возможности ещё не проверены.",
  "核验使用生成测试资料，可能产生模型与 Embedding 费用；Hindsight 会启动 Docker 服务与模型。不会读取或回填个人历史。": "Проверка использует сгенерированные тестовые данные и может повлечь расходы на модель и эмбеддинги; Hindsight запускает службу Docker и модели. Личная история не читается и не заполняется задним числом.",
  "已了解核验的连接与费用影响。": "Я понимаю, какие подключения и возможные расходы используются для проверки.",
