  "查看已安装插件": "Просмотреть установленные плагины",
  "离开此引导不会撤销已登记的安装或核验。": "Выход из этого мастера не отменяет уже зарегистрированную установку или проверку.",
  "填写连接配置。保存不会运行核验、启用插件或更换记忆方案。": "Введите настройки подключения. Сохранение не запускает проверку, не включает плагин и не меняет план памяти.",
