  "主题是模型整理的浏览视图，不代表新的用户事实。": "Темы — представления, организованные моделью, а не новые факты о вас.",
  "尚无自动主题；仍可浏览全部记忆和已有维度。": "Автоматических тем пока нет; вся память и существующие представления по-прежнему доступны.",
