  "已保存账号绑定不代表当前登录或读取权限有效。“重新检测”检查中央运行环境；请结合授权结果与同步步骤确认账号权限。": "Сохранённая привязка аккаунта не подтверждает действительный вход или права чтения. «Проверить снова» проверяет среду центрального узла; права аккаунта подтверждайте по результатам авторизации и шагам синхронизации.",
