  "结构化内容未采集：Chrome 窗口、站点授权或遮挡校验未通过；应用时长按所选设置记录": "Структурированный контент не захвачен: проверки окна Chrome, разрешения сайта или видимости не пройдены; длительность приложений записывается по вашему выбору",
  "切换语言会重新加载页面，请先保存未提交的修改。继续？": "Смена языка перезагрузит страницу. Сначала сохраните несохранённые изменения. Продолжить?",
  "无法保存语言偏好，请检查浏览器存储。": "Не удалось сохранить языковые настройки. Проверьте хранилище браузера.",
  "切换语言会重新加载界面，请先保存未提交的设置。继续？": "Смена языка перезагрузит окно. Сначала сохраните несохранённые настройки. Продолжить?",
